        private void LoadData()
        {
            try
            {
                _combatPlayers = _CombatPlayerData.ReadObject<CombatPlayers>();
                _CombatPlayerCache = _combatPlayers.combatPlayer;
            }
            catch
            {
                _combatPlayers = new CombatPlayers();
            }
            try
            {
                _ccThemes = _CCThemeData.ReadObject<CCThemes>();
                _ccthemeCache = _ccThemes.Theme;
            }
            catch
            {
                _ccThemes = new CCThemes();
            }
        }
        private void SaveData()
        {
            if (_combatPlayers != null)
            {
                _combatPlayers.combatPlayer = _CombatPlayerCache;
                _CombatPlayerData.WriteObject(_combatPlayers);
            }
            if (_ccThemes != null)
            {
                _ccThemes.Theme = _ccthemeCache;
                _CCThemeData.WriteObject(_ccThemes);
            }
        }
        #endregion

        #region Load/Save
        private void Init()
        {
            Instance = this;
            _CombatPlayerCache = new Dictionary<ulong, CombatPlayer>();
            _ClassPlayerCache = new Dictionary<string, Class>();
            _ccthemeCache = new Dictionary<ulong, Themes>();
            _CalculatorCache = new Dictionary<ulong, Calculator>();
        }

        /// <summary>
        /// Player JSON root: CustomDataDirectory when set (shared DataPersistence), else HarmonyData/CombatClasses.
        /// Images/avatars/themes live under oxide/data/CombatClasses (server-local assets) — see ResolveAssetDirectory.
        /// </summary>
        private bool UsesCustomDataDirectory =>
            config?.mainSettings != null && !string.IsNullOrWhiteSpace(config.mainSettings.CustomDataDirectory);

        private string CombatClassesDataRoot
        {
            get
            {
                if (UsesCustomDataDirectory)
                    return Path.GetFullPath(config.mainSettings.CustomDataDirectory.Trim());
                return Path.Combine(Interface.Oxide.DataDirectory, "CombatClasses");
            }
        }

        /// <summary>Server root (parent of RustDedicated_Data).</summary>
        private static string ServerRootPath =>
            Path.GetFullPath(Path.Combine(UnityEngine.Application.dataPath, ".."));

        /// <summary>Original Oxide asset folder: oxide/data/CombatClasses (images, Avatars, CCThemeData).</summary>
        private string OxideCombatClassesDir =>
            Path.Combine(ServerRootPath, "oxide", "data", "CombatClasses");

        /// <summary>
        /// Prefer oxide/data/CombatClasses/&lt;sub&gt; for UI assets (images/Avatars), then CustomDataDirectory, then HarmonyData.
        /// </summary>
        private string ResolveAssetDirectory(string subfolder)
        {
            string[] candidates =
            {
                Path.Combine(OxideCombatClassesDir, subfolder),
                Path.Combine(CombatClassesDataRoot, subfolder),
                Path.Combine(Interface.Oxide.DataDirectory, "CombatClasses", subfolder),
            };
            for (int i = 0; i < candidates.Length; i++)
            {
                if (Directory.Exists(candidates[i]))
                    return candidates[i];
            }
            return candidates[0];
        }

        private void EnsureCombatClassesDataDirectory()
        {
            try
            {
                var root = CombatClassesDataRoot;
                if (!Directory.Exists(root))
                    Directory.CreateDirectory(root);
            }
            catch (Exception ex)
            {
                PrintWarning($"EnsureCombatClassesDataDirectory: {ex.Message}");
            }
        }

        private DynamicConfigFile GetCombatClassesDataFile(string name)
        {
            EnsureCombatClassesDataDirectory();
            var fileName = name.EndsWith(".json", StringComparison.OrdinalIgnoreCase) ? name : name + ".json";

            // Player aggregate stays on CustomDataDirectory (shared). Theme data is usually next to images under oxide/data.
            string path = Path.Combine(CombatClassesDataRoot, fileName);
            if (!File.Exists(path) && !string.Equals(fileName, "CombatClassesData.json", StringComparison.OrdinalIgnoreCase))
            {
                var oxidePath = Path.Combine(OxideCombatClassesDir, fileName);
                if (File.Exists(oxidePath))
                    path = oxidePath;
            }

            var file = new DynamicConfigFile(path);
            if (File.Exists(path)) file.Load();
            return file;
        }

        private void HandlePermissions()
        {
            permission.RegisterPermission(PermAssault, this);
            permission.RegisterPermission(PermMedic, this);
            permission.RegisterPermission(PermHeavy, this);
            permission.RegisterPermission(PermDemolition, this);
            permission.RegisterPermission(PermSniper, this);
            permission.RegisterPermission(PermAssassin, this);
            permission.RegisterPermission(PermScavenger, this);
        }
        private void OnServerInitialized()
        {
            SaveConfig();
            EnsureCombatClassesDataDirectory();
            _CombatPlayerData = GetCombatClassesDataFile("CombatClassesData");
            _CCThemeData = GetCombatClassesDataFile("CCThemeData");

            cmd.AddChatCommand(config.mainSettings.openui, this, nameof(OpenCCUI));
            cmd.AddChatCommand(config.mainSettings.gearbox, this, nameof(GiveCombatGearBox));
            cmd.AddChatCommand(config.mainSettings.givexp, this, nameof(GiveXPChat));
            cmd.AddChatCommand("movecombat", this, nameof(MoveCombatHud));
            cmd.AddChatCommand("moveclasshud", this, nameof(MoveCombatHud));
            cmd.AddChatCommand("resetcombat", this, nameof(ResetCombatHud));

            HandlePermissions();

            LoadData();

            CheckAndInitializeMissingGearBoxes();

            LoadImages();

            BasePlayer.allPlayerList.ToList().ForEach(InitializeCombatPlayers);
            BasePlayer.activePlayerList.ToList().ForEach(OnPlayerConnected);

            SaveData();
            _isReady = true;
        }
        private void OnServerShutdown()
        {
            _isReady = false;
            SaveData();
        }
        private void Unload()
        {
            _isReady = false;
            SaveData();
            foreach (var player in BasePlayer.activePlayerList)
            {
                //if (!player.IsConnected || !player.isSpawned) continue;
                DestroyUIall(player);
            }
        }
