        #region Hooks
        private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo hitInfo)
        {
            if (entity == null || hitInfo == null || hitInfo.Initiator == null || entity == hitInfo.Initiator) return null;

            // Ignore Corpse
            if (entity.GetType().Name.ToLower().Contains("corpse")) return null;

            // Check if Gearbox
            var storageContainer = entity as StorageContainer;
            if(entity is StorageContainer)
            {
                if (storageContainer != null) 
                {
                    if (storageContainer.skinID == config.gearBox.SkinID) 
                    {
                        // Prevent Damage and Return. Cancel the hook (return non-null) so the
                        // game does not record lastDamage from an all-zero damage array, which
                        // GetMajorityDamageType() resolves to the last enum value (Cannon).
                        hitInfo.damageTypes.ScaleAll(0);
                        return true;
                    }
                }
            }

            // Check for Team/Clan
            if(entity is BasePlayer t1 && hitInfo.Initiator is BasePlayer t2)
            {
                if (config.mainSettings.useteams && config.mainSettings.allowteamkill && IsSameTeam(t1, t2)) return null;
                if (config.mainSettings.useclans && config.mainSettings.allowclankill && IsSameClan(t1, t2)) return null;
            }

            // Check if entity is a player
            if (entity is BasePlayer player)
            {
                // Reset passive healing timer
                ResetPassiveHealingTimer(player);

                // Reduce damage for classes
                ReduceDamage(player, hitInfo);

                // If a class fully blocked the hit, cancel the hook so the game does not stamp
                // lastDamage from a zeroed damage array (which resolves to a false Cannon death).
                if (hitInfo.damageTypes.Total() <= 0f) return true;
            }

            // Get Attacker
            var attacker = hitInfo.Initiator as BasePlayer;

            // If Attacker is Player Continue to Combat Classes
            if (attacker?.userID.IsSteamId() == true)
            {
                HandleAttackerDamage(attacker, entity, hitInfo);
                if (config.mainSettings.showdmgindicator) 
                { 
                    CCDmgIndicator(attacker, Math.Round(hitInfo.damageTypes.Total())); 
                }
            }

            return null;
        }
        private void OnEntityDeath(BaseCombatEntity entity, HitInfo hitInfo)
        {
            if (entity == null || hitInfo == null || hitInfo.Initiator == null || entity.gameObject == null) return;

            // Check if Attacker or Victim is Player
            if (entity is BasePlayer || hitInfo.Initiator is BasePlayer)
            {
                // Get Attacker
                //string attackerName = hitInfo.Initiator?.ShortPrefabName;
                string attackerName = GetNameBE(hitInfo.Initiator);
                var attacker = hitInfo.Initiator as BasePlayer;
                
                // Get Victim
                //string victimName = entity?.ShortPrefabName;
                string victimName = GetNameBCE(entity);
                var victim = entity as BasePlayer;

                // Handle Attacker
                if (attacker != null)
                {
                    // Check for team/clan
                    if (config.mainSettings.useteams && config.mainSettings.allowteamkill && IsSameTeam(attacker, victim)) return;
                    if (config.mainSettings.useclans && config.mainSettings.allowclankill && IsSameClan(attacker, victim)) return;
                    // Handle attacker kill
                    HandleKills(attacker, entity, hitInfo);
                }

                // Handle Victim
                if (victim != null)
                {
                    // Double Check for team/clan
                    if (config.mainSettings.useteams && config.mainSettings.allowteamkill && IsSameTeam(attacker, victim)) return;
                    if (config.mainSettings.useclans && config.mainSettings.allowclankill && IsSameClan(attacker, victim)) return;
                    // Handle victim death
                    HandleDeaths(victim, hitInfo);
                }
            }
        }
        private void OnPlayerRevive(BasePlayer reviver, BasePlayer player)
        {
            if (reviver == null || !reviver.userID.Get().IsSteamId() || player == null || !player.userID.Get().IsSteamId()) return;
            if (!player.IsWounded()) return;

            CombatPlayer combatPlayer = GetCombatPlayer(reviver);
            if (combatPlayer == null) return;

            var combatClass = GetClassData(combatPlayer.currentclass);
            if (combatClass == null) return;

            // Apply medic's revive health bonus based on class level
            if (combatClass is List<MedicSettings> medicSettingsList)
            {
                var medicSettings = medicSettingsList.FirstOrDefault();
                if (medicSettings != null)
                {
                    if (combatPlayer.combatclass.TryGetValue(combatPlayer.currentclass, out Class medicClass))
                    {
                        //double additionalHealth = medicSettings.revivehp + (medicSettings.revivehp * medicClass.level);
                        double additionalHealth = medicSettings.revivehp * medicClass.level;

                        player.health += (float)additionalHealth;
                        if (player.health > player.MaxHealth()) player.health = player.MaxHealth(); // Ensure health doesn't exceed max health

                        // send a message to the player being revived
                        player.ChatMessage($"{CCLang("CC_medic_002", player.UserIDString, additionalHealth, reviver.displayName)}");

                        // send a message to the reviver
                        reviver.ChatMessage($"{CCLang("CC_medic_003", player.UserIDString, player.displayName, additionalHealth)}");
                    }
                }
            }
        }
        private void OnPlayerRecovered(BasePlayer player)
        {
            if (player == null || !player.userID.Get().IsSteamId() || player.IsDead()) return;

            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null || combatPlayer.currentclass != "medic") return;

            var combatClass = GetClassData(combatPlayer.currentclass);
            if (combatClass == null || !(combatClass is List<MedicSettings> medicSettingsList)) return;

            var medicSettings = medicSettingsList.FirstOrDefault();
            if (medicSettings == null) return;

            // Calculate recover health based on class level and settings
            if (combatPlayer.combatclass.TryGetValue(combatPlayer.currentclass, out Class medicClass))
            {
                //double levelMultiplier = medicClass.level * medicSettings.healbonus;
                double recoverHealth = medicSettings.recoverhp * medicClass.level;

                player.health += (float)recoverHealth;
                if (player.health > player.MaxHealth()) player.health = player.MaxHealth(); // Ensure health doesn't exceed max health

                // Optionally, send a message to the player
                player.ChatMessage($"{CCLang("CC_medic_005", player.UserIDString, recoverHealth)}");
            }
        }
        private object OnHealingItemUse(MedicalTool tool, BasePlayer player)
        {
            var toolOwner = tool.GetOwnerPlayer();
            if (toolOwner == null || player == null || !toolOwner.userID.IsSteamId() || !player.userID.IsSteamId() || tool == null) return null;

            CombatPlayer combatPlayer = GetCombatPlayer(toolOwner);
            if (combatPlayer == null) return null;

            var combatClass = GetClassData(combatPlayer.currentclass);
            if (combatClass == null) return null;

            if(config.mainSettings.debug)
            {
                Puts("OnHealingItemUse \n");
            }

            switch (combatPlayer.currentclass)
            {
                case "medic":
                    var medicSettings = combatClass as MedicSettings;
                    if (medicSettings == null) return null;

                    if (config.mainSettings.debug)
                    {
                        Puts("Medic Class \n");
                    }

                    // Calculate heal bonus based on class level and settings
                    double levelMultiplier = combatPlayer.combatclass["medic"].level * medicSettings.healbonus;

                    if (config.mainSettings.debug)
                    {
                        Puts($"LevelMultiplier: {levelMultiplier} \n");
                    }

                    // Access consumable effects from the tool
                    var itemDef = tool.GetOwnerItemDefinition();
                    var consumable = itemDef?.GetComponent<ItemModConsumable>();

                    if (consumable != null)
                    {
                        foreach (var effect in consumable.effects)
                        {
                            if (effect.type == MetabolismAttribute.Type.Health)
                            {
                                bool isBandage = itemDef.shortname == "bandage";
                                float defaultamount = effect.amount;
                                double healBonus = effect.amount * levelMultiplier;
                                if (config.mainSettings.debug)
                                {
                                    Puts($"Base Heal: {defaultamount} \n");
                                    Puts($"HealBonus: {healBonus} \n");
                                }


                                // Apply medic bonus without mutating shared ItemModConsumable data (used by all items of this type).
                                var healAmount = effect.amount;
                                if (medicSettings.bandageboost || !isBandage)
                                    healAmount += (float)healBonus;

                                if (config.mainSettings.debug)
                                    Puts($"HealAmount: {healAmount} \n");

                                player.health += healAmount;
                                if (player.health > player.MaxHealth()) player.health = player.MaxHealth();

                                if (config.mainSettings.debug)
                                    Puts($"Added {healAmount} health to {player.displayName} \n");

                            }
                        }
                    }
                    return true;

                case "assault":
                    if (toolOwner != player) return null;
                    var assaultSettings = combatClass as AssaultSettings;
                    if (assaultSettings == null) return null;

                    ItemDefinition item = tool.GetOwnerItemDefinition();
                    Item pitem = player.GetActiveItem();

                    bool AdrenalineShot = item.shortname == "syringe.medical" && pitem.name == "Adrenaline Shot";

                    if (AdrenalineShot)
                    {
                        DateTime lastadrenalinesshot = combatPlayer.classtimer.AddSeconds(assaultSettings.adrenalinesshotduration);
                        TimeSpan interval = lastadrenalinesshot - DateTime.Now;
                        int timer = (int)interval.TotalSeconds;
                        if (timer > 0)
                        {
                            toolOwner.ChatMessage(CCLang("CC_assault_005", toolOwner.UserIDString, timer));
                            GiveAdrenalineShotPlayer(toolOwner);
                            return true;
                        }
                        else
                        {
                            combatPlayer.classtimer = DateTime.Now;
                            double resistance = Math.Round((assaultSettings.adrenalinesshotamount * combatPlayer.combatclass[combatPlayer.currentclass].level) * 100, 2);
                            toolOwner.ChatMessage(CCLang("CC_assault_004", toolOwner.UserIDString, resistance, assaultSettings.adrenalinesshotduration));
                            return true;
                        }
                    }
                    return null;
            }
            return null;
        }
        private void OnExplosiveThrown(BasePlayer player, BaseEntity entity, ThrownWeapon item)
        {
            if (player == null || entity == null || item == null) return;

            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null || combatPlayer.currentclass != "demolition") return;

            TimedExplosive timedExplosive = entity as TimedExplosive;
            if (timedExplosive == null) return;

            var demPlayer = combatPlayer.combatclass[combatPlayer.currentclass];
            var demSettings = config.classSettings.DemolitionClass[combatPlayer.currentclass];

            // Explosive Radius
            if (demSettings.explosiveradius != 0)
            {
                float defaultRadius = timedExplosive.explosionRadius;
                double radiusMultiplier = demPlayer.level * demSettings.explosiveradius;
                float newRadius = defaultRadius + (float)(defaultRadius * radiusMultiplier);
                timedExplosive.explosionRadius = newRadius;
            }

            // Explosive Damage
            if (demSettings.explosivedamage != 0)
            {
                foreach (DamageTypeEntry damageType in timedExplosive.damageTypes)
                {
                    float defaultDamage = damageType.amount;
                    double damageMultiplier = demPlayer.level * demSettings.explosivedamage;
                    float newDamage = defaultDamage + (float)(defaultDamage * damageMultiplier);
                    damageType.amount = newDamage;
                }
            }
        }
        private object OnExplosiveDud(DudTimedExplosive explosive)
        {
            // SkillTree owns dudless explosives — CombatClasses dud reduction disabled.
            return null;
        }
        private void OnRocketLaunched(BasePlayer player, BaseEntity entity)
        {
            if (player == null || entity == null) return;

            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null || combatPlayer.currentclass != "demolition") return;

            var demPlayer = combatPlayer.combatclass[combatPlayer.currentclass];
            var demSettings = config.classSettings.DemolitionClass[combatPlayer.currentclass];

            TimedExplosive rocket = entity.GetComponent<TimedExplosive>();
            if (rocket == null) return;

            Item item = player.GetActiveItem();
            if (item == null) return;

            BaseProjectile baseProjectile = item.GetHeldEntity() as BaseProjectile;
            if (baseProjectile == null) return;

            int rocketType = baseProjectile.primaryMagazine.ammoType.itemid;
            ServerProjectile serverProjectile = entity.GetComponent<ServerProjectile>();
            if (serverProjectile == null) return;

            // SkillTree owns rocket speed — skip when rocketspeed is 0.
            if (demSettings.rocketspeed != 0)
            {
                float defaultSpeed = serverProjectile.speed;
                float speedMultiplier = (float)(demSettings.rocketspeed * demPlayer.level);
                serverProjectile.speed = defaultSpeed * (1f + speedMultiplier);
            }

            // Adjust Rocket Damage (kept — SkillTree coexistence)
            if (demSettings.rocketdmg != 0)
            {
                foreach (DamageTypeEntry damageType in rocket.damageTypes)
                {
                    float defaultDamage = damageType.amount;
                    float damageMultiplier = (float)(demSettings.rocketdmg * demPlayer.level);
                    damageType.amount += defaultDamage * damageMultiplier;
                }
            }
        }
