        private void OnActiveItemChanged(BasePlayer player, Item oldItem, Item newItem)
        {
            // Safety: clear any temporary Eoka buff when weapon swapped
            if (player == null) return;
            var oldProj = oldItem?.GetHeldEntity() as BaseProjectile;
            var oldFlint = oldProj as FlintStrikeWeapon;
            if (oldFlint != null)
            {
                // Restore to default 0.5 if it was set to 1
                if (oldFlint.successFraction > 0.5f)
                {
                    oldFlint.successFraction = 0.5f;
                }
            }
        }
        private void OnItemCreated(Item item)
        {
            // Fix for Backpacks plugin InvalidCastException when restoring weapons with invalid mods
            // This validates weapon mods when items are created to prevent cast errors
            if (item == null || item.info == null) return;
            
            // Only process weapons
            if (item.info.category != ItemCategory.Weapon || item.contents == null) return;
            
            // Clean up invalid mods on next tick to avoid modifying during creation
            NextTick(() =>
            {
                try
                {
                    CleanupInvalidWeaponMods(item);
                }
                catch (Exception e)
                {
                    PrintError($"Error cleaning up weapon mods in OnItemCreated: {e.Message}");
                }
            });
        }
        private void OnItemAddedToContainer(ItemContainer container, Item item)
        {
            // Fix for Backpacks plugin InvalidCastException - validate mods when added to weapon containers
            if (container == null || item == null || item.info == null) return;
            
            // Check if this is a weapon container (weapon mod slots)
            // container.parent is already an Item, not something with GetItem()
            var parentItem = container.parent;
            if (parentItem == null || parentItem.info == null) return;
            
            // Only validate if parent is a weapon
            if (parentItem.info.category == ItemCategory.Weapon)
            {
                // Validate the mod being added
                if (!IsValidWeaponMod(item, parentItem))
                {
                    // Remove the invalid mod on next tick to avoid modifying during add
                    NextTick(() =>
                    {
                        try
                        {
                            item.RemoveFromContainer();
                            // Try to give it back to the player if possible
                            var player = container.playerOwner;
                            if (player != null)
                            {
                                player.GiveItem(item, BaseEntity.GiveItemReason.PickedUp);
                            }
                        }
                        catch (Exception e)
                        {
                            PrintError($"Error removing invalid mod in OnItemAddedToContainer: {e.Message}");
                        }
                    });
                }
            }
        }
