        private void OnPlayerInput(BasePlayer player, InputState input)
        {
            // Patches apply before OnServerInitialized; skip until caches/config are ready.
            if (!_isReady || player == null || input == null) return;
            if (config?.classSettings == null || _CombatPlayerCache == null) return;

            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null || string.IsNullOrEmpty(combatPlayer.currentclass)) return;

            ulong playerId = player.userID;
            bool reloadDown = input.IsDown(BUTTON.RELOAD);
            bool useDown = input.IsDown(BUTTON.USE);

            // Initialize dictionaries if they don't already contain the player ID
            if (!reloadStartTimes.ContainsKey(playerId)) reloadStartTimes[playerId] = null;
            if (!useStartTimes.ContainsKey(playerId)) useStartTimes[playerId] = null;
            if (!lastSniperScanTimes.ContainsKey(playerId)) lastSniperScanTimes[playerId] = null;
            if (!lastSmokeDeployTimes.ContainsKey(playerId)) lastSmokeDeployTimes[playerId] = null;
            if (!lastGrenadeDeployTimes.ContainsKey(playerId)) lastGrenadeDeployTimes[playerId] = null;
            if (!lastAssaultAdrenalineTimes.ContainsKey(playerId)) lastAssaultAdrenalineTimes[playerId] = null;

            switch (combatPlayer.currentclass)
            {
                case "assault":
                    if (!config.classSettings.AssaultClass.TryGetValue(combatPlayer.currentclass, out var assaultSettings) || assaultSettings == null)
                        break;
                    // Both buttons together = Smoke Grenade
                    if (reloadDown && useDown)
                    {
                        HandleGrenadeDeployment(input, player, playerId, assaultSettings.smokedeploytimer, lastSmokeDeployTimes, "Smoke Grenade", ThrowSmokeGrenade);
                    }
                    // USE alone = Adrenaline Shot
                    else if (useDown && !reloadDown)
                    {
                        HandleAssaultAdrenalineHelper(input, player, playerId, assaultSettings.adrenalinesshottimer, lastAssaultAdrenalineTimes);
                    }
                    break;
                case "heavy":
                    if (!config.classSettings.HeavyClass.TryGetValue(combatPlayer.currentclass, out var heavySettings) || heavySettings == null)
                        break;
                    if (input.IsDown(BUTTON.RELOAD)) { HandleGrenadeDeployment(input, player, playerId, heavySettings.grenadedeploytimer, lastGrenadeDeployTimes, "F1 Grenade", ThrowGrenade); }
                    break;
                case "sniper":
                    if (!config.classSettings.SniperClass.TryGetValue(combatPlayer.currentclass, out var sniperSettings) || sniperSettings == null)
                        break;
                    if (input.IsDown(BUTTON.RELOAD)) { HandleSniperScan(input, player, playerId, sniperSettings.scantimer, lastSniperScanTimes); }
                    break;
                case "scavenger":
                    if (!config.classSettings.ScavengerClass.TryGetValue(combatPlayer.currentclass, out var scavSettings) || scavSettings == null)
                        break;
                    if (input.IsDown(BUTTON.RELOAD)) { HandleScavengerTapReady(input, player, playerId, scavSettings); }
                    break;
            }
            if(input.WasJustReleased(BUTTON.RELOAD) || input.WasJustReleased(BUTTON.USE))
            {
                reloadStartTimes[playerId] = null;
                useStartTimes[playerId] = null;
            }
        }
        private object OnPlayerChat(BasePlayer player, string message, Chat.ChatChannel channel)
        {
            if (player == null || string.IsNullOrEmpty(message)) return null;

            // Check if showchatclass is enabled
            if (!config.mainSettings.showchatclass) return null;

            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return null;

            var combatClass = combatPlayer.currentclass;
            if (string.IsNullOrEmpty(combatClass)) return null;

            // Prefix format
            string classPrefix = $"[{combatClass.ToUpper()}] ";
            string playerNameWithPrefix = $"{classPrefix}{player.displayName}";
            string modifiedMessage = $"{message}";

            // Create and send the chat message
            foreach (var activePlayer in BasePlayer.activePlayerList)
            {
                var chatArray = new string[]
                {
                    ((int)channel).ToString(),
                    player.UserIDString,
                    $"{playerNameWithPrefix}: {modifiedMessage}"
                };

                activePlayer.SendConsoleCommand("chat.add", chatArray);
            }

            // Prevent the original chat message from being sent
            return true;
        }
        private object OnConstructionPlace(BaseEntity entity, Construction component, Construction.Target constructionTarget, BasePlayer player)
        {
            if (player == null || !player.userID.Get().IsSteamId() || entity == null) return null;
            var storageContainer = entity as StorageContainer;
            if (storageContainer == null) return null;
            if (storageContainer.skinID != config.gearBox.SkinID) return null;
            
            // Try to change info (still testing)
            storageContainer.onlyOneUser = true;
            storageContainer.name = config.gearBox.DisplayName;
            storageContainer.panelTitle = new Translate.Phrase(config.gearBox.DisplayName.ToLower(), config.gearBox.DisplayName);
            storageContainer.panelTitle.english = config.gearBox.DisplayName;
            storageContainer.health = storageContainer.MaxHealth();
            storageContainer.SendChildrenNetworkUpdateImmediate();
            storageContainer.SendNetworkUpdateImmediate();

            return null;
        }
        private object CanPickupEntity(BasePlayer player, BaseEntity entity)
        {
            if (player == null || entity == null || !player.userID.Get().IsSteamId()) return null;

            var storageContainer = entity as StorageContainer;
            if (storageContainer == null || storageContainer.skinID != config.gearBox.SkinID) return null;

            if (storageContainer.skinID == config.gearBox.SkinID && player.IsAdmin)
            {
                storageContainer.health = storageContainer.MaxHealth();
                return true;
            }

            return false;
        }
        private object CanLootEntity(BasePlayer player, StorageContainer container)
        {
            if (player == null || container == null) return null;
            if (container.skinID != config.gearBox.SkinID) return null;

            // Initialize the player's cooldown time if it doesn't already exist
            if (!lastGearBoxTimes.ContainsKey(player.userID))
            {
                lastGearBoxTimes[player.userID] = null;
            }

            var lastAccessTime = lastGearBoxTimes[player.userID];

            // Allow access if the player hasn't accessed the box before
            if (lastAccessTime == null)
            {
                lastGearBoxTimes[player.userID] = DateTime.Now;
                return null;
            }

            // Check cooldown timer
            if ((DateTime.Now - lastAccessTime.Value).TotalSeconds < config.gearBox.accesstimer)
            {
                double remainingCooldown = config.gearBox.accesstimer - (DateTime.Now - lastAccessTime.Value).TotalSeconds;
                player.ChatMessage(CCLang("gearcooldown", player.UserIDString, Math.Round(remainingCooldown)));
                return false;
            }

            // Allow access and update the last access time
            lastGearBoxTimes[player.userID] = DateTime.Now;
            return null;
        }
        private void OnLootEntity(BasePlayer player, BaseEntity entity)
        {
            if (player == null || entity == null) return;
            if (entity is StorageContainer gearbox && gearbox.skinID == config.gearBox.SkinID)
            {
                CombatPlayer combatPlayer = GetCombatPlayer(player);
                if (combatPlayer == null) return;
                GetGearBoxContent(combatPlayer.currentclass, gearbox);
            }
        }
        private void OnLootEntityEnd(BasePlayer player, BaseCombatEntity entity)
        {
            if (player == null || entity == null) return;
            if (entity is StorageContainer gearbox && gearbox.skinID == config.gearBox.SkinID)
            {
                gearbox.inventory.Kill();
                gearbox.inventory.Clear();
                gearbox.SendNetworkUpdateImmediate();
            }
        }
