        // Combat Gear
        #region Gear
        private void CheckAndInitializeMissingGearBoxes()
        {
            var allClasses = new List<string> { "assault", "medic", "heavy", "sniper", "demolition", "assassin", "scavenger" };
            foreach (var className in allClasses)
            {
                if (!config.gearBox.classBox.ContainsKey(className))
                {
                    config.gearBox.classBox.Add(className, new ClassBox
                    {
                        classBoxGear = new SortedDictionary<int, ClassGear>()
                    });
                }
            }
        }
        private void GetGearBoxContent(string combatClass, StorageContainer gearbox)
        {
            if (string.IsNullOrEmpty(combatClass) || gearbox == null) return;

            if (!config.gearBox.classBox.ContainsKey(combatClass)) return;

            gearbox.inventory.Kill();
            gearbox.inventory.Clear();
            gearbox.SendChildrenNetworkUpdateImmediate();

            foreach (var item in config.gearBox.classBox[combatClass].classBoxGear)
            {
                // Create each Item
                var gear = ItemManager.CreateByName(item.Value.ShortPrefabName, item.Value.amount, item.Value.skinID);

                if (item.Value.DisplayName != string.Empty)
                { 
                    gear.name = item.Value.DisplayName; 
                }
                if (item.Value.skinID != 0) 
                { 
                    gear.skin = item.Value.skinID; 
                }

                gear.MarkDirty();
                gear.MoveToContainer(gearbox.inventory);
            }

            gearbox.SendChildrenNetworkUpdateImmediate();
        }
        private void GiveCombatGear(BasePlayer player, string CombatClass)
        {
            if (player == null || !player.userID.Get().IsSteamId()) return;

            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            var ClassGear = config.gearBox.classBox[CombatClass].classBoxGear;
            if (ClassGear == null) return;

            foreach (var gear in ClassGear)
            {
                Item createitem = ItemManager.CreateByName(gear.Value.ShortPrefabName, gear.Value.amount, gear.Value.skinID);
                createitem.name = gear.Value.DisplayName;
                createitem.info.name = gear.Value.DisplayName;
                createitem.MarkDirty();
                if (createitem == null)
                {
                    Puts($"Failed to give Combat Gear to {player.displayName}. Check your config for proper values.");
                    return;
                }
               
                // If wearable and auto equip enabled put on player
                if (config.mainSettings.autoequip && createitem.CanMoveTo(player.inventory.containerWear))
                {
                    createitem.MoveToContainer(player.inventory.containerWear);
                }
                // If weapon and auto equip enabled put in belt
                else if (config.mainSettings.autoequip && createitem.CanMoveTo(player.inventory.containerBelt))
                {
                    createitem.MoveToContainer(player.inventory.containerBelt);
                }
                // all other items or auto equip disabled put in player inventory
                else
                {
                    player.GiveItem(createitem);
                }
                player.SendNetworkUpdateImmediate();
            }

            combatPlayer.givegear = false;
            player.ChatMessage($"{CCLang("givegear", player.UserIDString, CCLang(CombatClass, player.UserIDString))}");
        }
