        private CombatPlayer GetCombatPlayer(BasePlayer player)
        {
            if (player == null || !player.userID.Get().IsSteamId()) return null;
            if (_CombatPlayerCache == null) return null;

            if (!_CombatPlayerCache.TryGetValue(player.userID, out var combatPlayer))
            {
                _CombatPlayerCache.Add(player.userID, new CombatPlayer
                {
                    displayname = player.displayName,
                    started = DateTime.Now,
                    classchange = DateTime.Now,
                    classtimer = DateTime.Now,
                    npckills = 0,
                    playerkills = 0,
                    deaths = 0,
                    suicides = 0,
                    currentclass = config.mainSettings.defaultclass,
                    givegear = false,
                    cc_hud_offset = Vector2.zero,
                    combatclass = new Dictionary<string, Class>()
                });

                CheckAndInitializeMissingClasses(player);
            }

            return combatPlayer;
        }
