                if(_combatPlayers.combatPlayer[userId].combatclass.ContainsKey(combatclass)) return;
                _combatPlayers.combatPlayer[userId].combatclass.Add(combatclass, new Class
                {
                    xp = 0,
                    xptotal = 0,
