        private object GetClassData(string combatclass)
        {
            if (string.IsNullOrEmpty(combatclass))
            {
                Puts($"Error: Combat class is null or empty. Combat Class: {combatclass}");
                return null;
            }

            if (config.classSettings.AssaultClass.TryGetValue(combatclass, out var assaultSettings)) return assaultSettings;
            if (config.classSettings.MedicClass.TryGetValue(combatclass, out var medicSettings)) return medicSettings;
            if (config.classSettings.HeavyClass.TryGetValue(combatclass, out var heavySettings)) return heavySettings;
            if (config.classSettings.SniperClass.TryGetValue(combatclass, out var sniperSettings)) return sniperSettings;
            if (config.classSettings.DemolitionClass.TryGetValue(combatclass, out var demolitionSettings)) return demolitionSettings;
            if (config.classSettings.AssassinClass.TryGetValue(combatclass, out var assassinSettings)) return assassinSettings;
            if (config.classSettings.ScavengerClass.TryGetValue(combatclass, out var scavengerSettings)) return scavengerSettings;

            Puts($"Error: Combat class not found in configuration. Combat Class: {combatclass}");
            return null;
        }
        private bool IsSameTeam(BasePlayer player, BasePlayer playercheck)
        {
            if (player == null || playercheck == null) return false;

            // Check if they are on the same team
            if (player.Team != null && playercheck.Team != null && player.Team == playercheck.Team) return true;

            return false;
        }
        private bool IsSameClan(BasePlayer player, BasePlayer playercheck)
        {
            if (player == null || playercheck == null) return false;

            IClan clan1 = player.serverClan;
            IClan clan2 = playercheck.serverClan;
            if (clan1 == null || clan2 == null) return false;

            return clan1 == clan2;
        }
