        // Level / XP
        #region Level / XP
        private void GiveXP(BasePlayer player, int xp)
        {
            if (player == null) return;
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            if (combatPlayer.combatclass[combatPlayer.currentclass].level >= config.mainSettings.maxlevel) return;

            combatPlayer.combatclass[combatPlayer.currentclass].xp += xp;
            combatPlayer.combatclass[combatPlayer.currentclass].xptotal += xp;

            int reqxp = (config.mainSettings.levelstart * combatPlayer.combatclass[combatPlayer.currentclass].level) + (int)Math.Ceiling((combatPlayer.combatclass[combatPlayer.currentclass].level * config.mainSettings.xpleveldifficultyincrease) * config.mainSettings.levelstart);
            if (combatPlayer.combatclass[combatPlayer.currentclass].level == 0)
            {
                reqxp = config.mainSettings.levelstart;
            }
            if (combatPlayer.combatclass[combatPlayer.currentclass].xp >= reqxp)
            {
                int remaining = combatPlayer.combatclass[combatPlayer.currentclass].xp - reqxp;
                LvlUp(player, remaining);
            }
            CCHUD(player);
        }
        private void LvlUp(BasePlayer player, int xp)
        {
            if (player == null) return;
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            if (combatPlayer.combatclass[combatPlayer.currentclass].level >= config.mainSettings.maxlevel && !config.mainSettings.enableranks)
            {
                combatPlayer.combatclass[combatPlayer.currentclass].level = config.mainSettings.maxlevel;
                return;
            }

            combatPlayer.combatclass[combatPlayer.currentclass].level++;
            combatPlayer.combatclass[combatPlayer.currentclass].xp = 0;

            int level = combatPlayer.combatclass[combatPlayer.currentclass].level;

            player.ChatMessage(CCLang("CC_012", player.UserIDString, CCLang(combatPlayer.currentclass, player.UserIDString), combatPlayer.combatclass[combatPlayer.currentclass].level));

            // Trigger level up event
            TriggerClassLevelUp(player.userID, combatPlayer.currentclass, combatPlayer.combatclass[combatPlayer.currentclass].level);

            if (combatPlayer.combatclass[combatPlayer.currentclass].level >= config.mainSettings.maxlevel && config.mainSettings.enableranks)
            {
                RankUp(player);
            }

            if (xp > 0) GiveXP(player, xp);
            CCHUD(player);

            if (config.mainSettings.showlevels)
            {
                GlobalLevelNotice(player.displayName, level, combatPlayer.currentclass);
            }

        }
