        private void LvlUpAllClasses(BasePlayer player, int xp)
        {
            if (player == null) return;
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            foreach (var classEntry in combatPlayer.combatclass)
            {
                var className = classEntry.Key;
                var combatClass = classEntry.Value;

                if (combatClass.level >= config.mainSettings.maxlevel && !config.mainSettings.enableranks)
                {
                    combatClass.level = config.mainSettings.maxlevel;
                    continue;
                }

                int reqxp = (config.mainSettings.levelstart * combatClass.level) + (int)Math.Ceiling((combatClass.level * config.mainSettings.xpleveldifficultyincrease) * config.mainSettings.levelstart);
                if (combatClass.level == 0)
                {
                    reqxp = config.mainSettings.levelstart;
                }

                if (combatClass.xp >= reqxp)
                {
                    int remaining = combatClass.xp - reqxp;
                    combatClass.xp = 0; // Reset XP for the next level up check
                    LvlUpClass(player, className, remaining);

                    player.ChatMessage(CCLang("CC_012", player.UserIDString, CCLang(className, player.UserIDString), combatClass.level));

                    // Trigger level up event
                    TriggerClassLevelUp(player.userID, className, combatClass.level);

                    if (combatClass.level >= config.mainSettings.maxlevel && config.mainSettings.enableranks)
                    {
                        RankUp(player);
                    }
                }
            }

            CCHUD(player);
        }
        private void TakeXP(BasePlayer player, int xp)
        {
            if (player == null || !config.mainSettings.losexp) return;
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            combatPlayer.combatclass[combatPlayer.currentclass].xp -= xp;
            combatPlayer.combatclass[combatPlayer.currentclass].xptotal -= xp;

            if (combatPlayer.combatclass[combatPlayer.currentclass].xptotal <= 0)
            {
                combatPlayer.combatclass[combatPlayer.currentclass].level = 0;
                combatPlayer.combatclass[combatPlayer.currentclass].xp = 0;
                combatPlayer.combatclass[combatPlayer.currentclass].xptotal = 0;
                return;
            }
            if (combatPlayer.combatclass[combatPlayer.currentclass].xp < 0)
            {
                LvlDown(player, Math.Abs(combatPlayer.combatclass[combatPlayer.currentclass].xp));
            }
            CCHUD(player);
        }
        private void LvlDown(BasePlayer player, int xp)
        {
            if (player == null) return;
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            if (combatPlayer.combatclass[combatPlayer.currentclass].level <= 0)
            {
                combatPlayer.combatclass[combatPlayer.currentclass].level = 0;
                return;
            }

            combatPlayer.combatclass[combatPlayer.currentclass].level--;

            int reqxp = (config.mainSettings.levelstart * combatPlayer.combatclass[combatPlayer.currentclass].level) + (int)Math.Ceiling((combatPlayer.combatclass[combatPlayer.currentclass].level * config.mainSettings.xpleveldifficultyincrease) * config.mainSettings.levelstart);

            combatPlayer.combatclass[combatPlayer.currentclass].xp = reqxp - xp;

            player.ChatMessage(CCLang("CC_029", player.UserIDString, CCLang(combatPlayer.currentclass, player.UserIDString), combatPlayer.combatclass[combatPlayer.currentclass].level));

            // Trigger level down event
            TriggerClassLevelDown(player.userID, combatPlayer.currentclass, combatPlayer.combatclass[combatPlayer.currentclass].level);

            // Repeat if xp lost goes beyond 1 level
            if (combatPlayer.combatclass[combatPlayer.currentclass].xp < 0)
            {
                LvlDown(player, Math.Abs(combatPlayer.combatclass[combatPlayer.currentclass].xp));
            }
            CCHUD(player);
        }
        private void RankUp(BasePlayer player)
        {
            if (player == null) return;
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            if (combatPlayer.combatclass[combatPlayer.currentclass].rank >= config.mainSettings.maxrank)
            {
                combatPlayer.combatclass[combatPlayer.currentclass].rank = config.mainSettings.maxrank;
                combatPlayer.combatclass[combatPlayer.currentclass].level = config.mainSettings.maxlevel;
                combatPlayer.combatclass[combatPlayer.currentclass].xp = 0;
                return;
            }
            combatPlayer.combatclass[combatPlayer.currentclass].rank++;
            combatPlayer.combatclass[combatPlayer.currentclass].level = 0;
            combatPlayer.combatclass[combatPlayer.currentclass].xp = 0;

            player.ChatMessage(CCLang("CC_013", player.UserIDString, CCLang(combatPlayer.currentclass, player.UserIDString), combatPlayer.combatclass[combatPlayer.currentclass].rank));
            CCHUD(player);
        }
        private int GetNPCXP(BaseCombatEntity entity)
        {
            if (entity == null) return 0;

            string entityPrefabName = entity.ShortPrefabName;
            string entityDisplayName = entity.ToPlayer()?.displayName;

            foreach (var npc in config.npcList.npcList.Values)
            {
                if (entityPrefabName == npc.ShortPrefabName)
                {
                    if (entityDisplayName != string.Empty && entityDisplayName == npc.DisplayName)
                    {
                        return npc.xp;
                    }
                    return npc.xp;
                }
            }

            return 0;
        }
        private double GetLevelPercent(CombatPlayer player, string combatclass)
        {
            if (player == null || combatclass == string.Empty) return 0;

            var getClass = player.combatclass[combatclass];
            int currentLevel = getClass.level;

            // Calculate required XP for the current level
            double reqxp = Math.Round((config.mainSettings.levelstart * currentLevel) + (currentLevel * config.mainSettings.xpleveldifficultyincrease) * config.mainSettings.levelstart, 2);
            if (currentLevel == 0) 
            { 
                reqxp = config.mainSettings.levelstart; 
            }
            int currentxp = getClass.xp;

            // Calculate the percentage
            return Math.Round((currentxp / reqxp) * 100, 2);
        }
        private int GetLevelRequirement(CombatPlayer player, string combatclass)
        {
            if (player == null || combatclass == string.Empty) return config.mainSettings.levelstart;

            var getClass = player.combatclass[combatclass];
            int currentLevel = getClass.level;

            // Calculate required XP for the current level
            int reqxp = (int)Math.Ceiling((config.mainSettings.levelstart * currentLevel) + (currentLevel * config.mainSettings.xpleveldifficultyincrease) * config.mainSettings.levelstart);
            if (currentLevel == 0) 
            { 
                reqxp = config.mainSettings.levelstart; 
            }

            // Calculate the percentage
            return reqxp;
        }
        private void CombatClassPermission(BasePlayer player)
        {
            if (player == null) return;
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            // Revoke all class permissions
            RevokeAllClassPermissions(player.UserIDString);

            // Grant permission based on the current class
            GrantClassPermission(player.UserIDString, combatPlayer.currentclass);
        }
        private void RevokeAllClassPermissions(string userId)
        {
            permission.RevokeUserPermission(userId, PermAssault);
            permission.RevokeUserPermission(userId, PermMedic);
            permission.RevokeUserPermission(userId, PermHeavy);
            permission.RevokeUserPermission(userId, PermDemolition);
            permission.RevokeUserPermission(userId, PermSniper);
            permission.RevokeUserPermission(userId, PermAssassin);
            permission.RevokeUserPermission(userId, PermScavenger);
        }
        private void GrantClassPermission(string userId, string combatClass)
        {
            string permissionName = combatClass switch
            {
                "assault" => PermAssault,
                "medic" => PermMedic,
                "heavy" => PermHeavy,
                "demolition" => PermDemolition,
                "sniper" => PermSniper,
                "assassin" => PermAssassin,
                "scavenger" => PermScavenger,
                _ => null
            };

            if (permissionName != null && !permission.UserHasPermission(userId, permissionName))
            {
                permission.GrantUserPermission(userId, permissionName, this);
            }
        }
