        // Damage
        #region Damage
        private void HandleAttackerDamage(BasePlayer player, BaseCombatEntity entity, HitInfo hitInfo)
        {
            if (!player.userID.Get().IsSteamId()) return;

            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            var combatClass = GetClassData(combatPlayer.currentclass);
            if (combatClass == null) return;

            var weaponEntity = hitInfo.Weapon;
            if (weaponEntity == null) return;

            var item = weaponEntity.GetItem();
            if (item == null) return;

            string weaponShortName = item.info.shortname;

            // Process class-specific modifications with the weapon shortname
            ProcessClassWeaponModifications(combatClass, weaponShortName, hitInfo);
        }
        private void ProcessClassWeaponModifications(object combatClass, string weaponShortName, HitInfo hitInfo)
        {
            switch (combatClass)
            {
                case AssaultSettings assaultSettings:
                    ApplyWeaponModifications(assaultSettings, weaponShortName, hitInfo);
                    break;
                case MedicSettings medicSettings:
                    ApplyWeaponModifications(medicSettings, weaponShortName, hitInfo);
                    break;
                case HeavySettings heavySettings:
                    ApplyWeaponModifications(heavySettings, weaponShortName, hitInfo);
                    break;
                case SniperSettings sniperSettings:
                    ApplyWeaponModifications(sniperSettings, weaponShortName, hitInfo);
                    break;
                case DemolitionSettings demolitionSettings:
                    ApplyWeaponModifications(demolitionSettings, weaponShortName, hitInfo);
                    break;
                case AssassinSettings assassinSettings:
                    ApplyWeaponModifications(assassinSettings, weaponShortName, hitInfo);
                    break;
                case ScavengerSettings scavengerSettings:
                    ApplyWeaponModifications(scavengerSettings, weaponShortName, hitInfo);
                    break;
            }
        }
        private void ApplyClassWeaponDamageIncrease(object combatClass, HitInfo hitInfo)
        {
            var weaponEntity = hitInfo.Weapon;
            if (weaponEntity == null) return;

            var item = weaponEntity.GetItem();
            if (item == null) return;

            string weaponShortName = item.info.shortname;

            switch (combatClass)
            {
                case List<AssaultSettings> assaultClass:
                    ApplyWeaponModifications(assaultClass.FirstOrDefault(), weaponShortName, hitInfo);
                    break;
                case List<MedicSettings> medicClass:
                    ApplyWeaponModifications(medicClass.FirstOrDefault(), weaponShortName, hitInfo);
                    break;
                case List<HeavySettings> heavyClass:
                    ApplyWeaponModifications(heavyClass.FirstOrDefault(), weaponShortName, hitInfo);
                    break;
                case List<SniperSettings> sniperClass:
                    ApplyWeaponModifications(sniperClass.FirstOrDefault(), weaponShortName, hitInfo);
                    break;
                case List<DemolitionSettings> demolitionClass:
                    ApplyWeaponModifications(demolitionClass.FirstOrDefault(), weaponShortName, hitInfo);
                    break;
                case List<AssassinSettings> assassinClass:
                    ApplyWeaponModifications(assassinClass.FirstOrDefault(), weaponShortName, hitInfo);
                    break;
            }
        }
        private void ApplyWeaponModifications(object classSettings, string weaponShortName, HitInfo hitInfo)
        {
            if (classSettings == null) return;

            // Define a helper method to apply damage modifications
            void ApplyDamageModifications(string mainWeapon, string secondaryWeapon, double mainDamageIncrease, double secondaryDamageIncrease, double maxDamageIncrease, double damageReduction, double longRangeAddition, double mediumRangeAddition, double closeRangeAddition)
            {
                // Check and apply main weapon modifications
                if (weaponShortName == mainWeapon)
                {
                    ApplyDamageIncrease(hitInfo, mainDamageIncrease, maxDamageIncrease);
                    ApplyRangeAddition(hitInfo, longRangeAddition, mediumRangeAddition, closeRangeAddition);
                }
                // Check and apply secondary weapon modifications
                else if (weaponShortName == secondaryWeapon)
                {
                    ApplyDamageIncrease(hitInfo, secondaryDamageIncrease, maxDamageIncrease);
                    ApplyRangeAddition(hitInfo, longRangeAddition, mediumRangeAddition, closeRangeAddition);
                }
                // Apply damage reduction to all other weapons
                else
                {
                    ApplyDamageReduction(hitInfo, (float)damageReduction);
                }
            }

            // Check the type of class settings and apply damage modifications accordingly
            switch (classSettings)
            {
                case AssaultSettings settings:
                    ApplyDamageModifications(settings.mainweapon, settings.secondaryweapon, settings.dmgincreasemain, settings.dmgincreasesecondary, settings.dmgmaxincrease, settings.dmgreduction, 0, settings.mediumrangeaddition, 0);
                    break;
                case MedicSettings settings:
                    ApplyDamageModifications(settings.mainweapon, settings.secondaryweapon, settings.dmgincreasemain, settings.dmgincreasesecondary, settings.dmgmaxincrease, settings.dmgreduction, 0, 0, 0);
                    break;
                case HeavySettings settings:
                    ApplyDamageModifications(settings.mainweapon, settings.secondaryweapon, settings.dmgincreasemain, settings.dmgincreasesecondary, settings.dmgmaxincrease, settings.dmgreduction, 0, 0, 0);
                    break;
                case SniperSettings settings:
                    ApplyDamageModifications(settings.mainweapon, settings.secondaryweapon, settings.dmgincreasemain, settings.dmgincreasesecondary, settings.dmgmaxincrease, settings.dmgreduction, settings.longrangeaddition, 0, 0);
                    break;
                case DemolitionSettings settings:
                    ApplyDamageModifications(settings.mainweapon, settings.secondaryweapon, settings.dmgincreasemain, settings.dmgincreasesecondary, settings.dmgmaxincrease, settings.dmgreduction, 0, 0, 0);
                    break;
                case AssassinSettings settings:
                    ApplyDamageModifications(settings.mainweapon, settings.secondaryweapon, settings.dmgincreasemain, settings.dmgincreasesecondary, settings.dmgmaxincrease, settings.dmgreduction, 0, 0, settings.closerangeaddition);
                    ApplyMeleeDamageBonus(settings, weaponShortName, hitInfo);
                    break;
                case ScavengerSettings settings:
                    ApplyDamageModifications(settings.mainweapon, settings.secondaryweapon, settings.dmgincreasemain, settings.dmgincreasesecondary, settings.dmgmaxincrease, settings.dmgreduction, 0, 0, 0);
                    break;
            }
        }
        private void ApplyRangeAddition(HitInfo hitInfo, double longRangeAddition, double mediumRangeAddition, double closeRangeAddition)
        {
            // Apply the appropriate range addition
            if (longRangeAddition != 0)
            {
                hitInfo.Weapon.LongRangeAddition += (float)longRangeAddition;
            }
            if (mediumRangeAddition != 0)
            {
                hitInfo.Weapon.MediumRangeAddition += (float)mediumRangeAddition;
            }
            if (closeRangeAddition != 0)
            {
                hitInfo.Weapon.CloseRangeAddition += (float)closeRangeAddition;
            }
        }
        private void ApplyDamageReduction(HitInfo hitInfo, float damageReduction)
        {
            foreach (DamageType damageType in Enum.GetValues(typeof(DamageType)))
            {
                if (damageType == DamageType.LAST) continue; // Skip DamageType.LAST

                try
                {
                    float currentDamage = hitInfo.damageTypes.Get(damageType);
                    if (currentDamage > 0)
                    {
                        float newDamage = currentDamage - (currentDamage * damageReduction);
                        if (newDamage > 0)
                        { 
                            hitInfo.damageTypes.Set(damageType, newDamage); 
                        }
                    }
                }
                catch (IndexOutOfRangeException ex)
                {
                    Puts($"Error applying damage reduction for damage type {damageType}: {ex.Message}");
                }
            }
        }
        private void ApplyDamageIncrease(HitInfo hitInfo, double damageIncrease, double maxIncrease)
        {
            if (hitInfo.damageTypes != null)
            {
                double baseDamage = hitInfo.damageTypes.Total();
                double increaseAmount = baseDamage * damageIncrease;
                double totalDamageIncrease = Math.Min(increaseAmount, baseDamage * maxIncrease);
                float scaleAmount = (float)(totalDamageIncrease / baseDamage);

                // Apply damage increase with bounds checking, excluding DamageType.LAST
                foreach (DamageType damageType in Enum.GetValues(typeof(DamageType)))
                {
                    if (damageType == DamageType.LAST) continue; // Skip DamageType.LAST

                    try
                    {
                        float currentDamage = hitInfo.damageTypes.Get(damageType);
                        hitInfo.damageTypes.Set(damageType, currentDamage * (1 + scaleAmount));
                    }
                    catch (IndexOutOfRangeException ex)
                    {
                        Puts($"Error applying damage increase for damage type {damageType}: {ex.Message}");
                    }
                }
            }
        }
        private bool IsValidNPC(BaseCombatEntity entity)
        {
            if (entity == null) return false;
            foreach (var npcs in config.npcList.npcList.Values)
            {
                if(entity.ShortPrefabName == npcs.ShortPrefabName) return true;
            }
            return false;
        }
        private bool IsSpecialNPC(BaseCombatEntity entity)
        {
            if (entity == null) return false;
            foreach (var npcs in config.npcList.npcList.Values)
            {
                if(entity.ShortPrefabName == npcs.ShortPrefabName && entity.ToPlayer().displayName == npcs.DisplayName) return true;
            }
            return false;
        }
        private void ReduceDamage(BasePlayer player, HitInfo hitInfo)
        {
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            var combatClass = combatPlayer.combatclass[combatPlayer.currentclass];
            if (combatClass == null) return;

            switch (combatPlayer.currentclass)
            {
                case "assault":
                    var assaultSettings = config.classSettings.AssaultClass[combatPlayer.currentclass];

                    DateTime lastAdrenalineShot = combatPlayer.classtimer.AddSeconds(assaultSettings.adrenalinesshotduration);
                    TimeSpan interval = lastAdrenalineShot - DateTime.Now;
                    int timer = (int)interval.TotalMinutes;
                    if (timer > 0) return;

                    float damageResistance = combatClass.level * (float)assaultSettings.adrenalinesshotamount;
                    ApplyDamageReduction(hitInfo, damageResistance);
                    break;

                case "heavy":
                    var heavySettings = config.classSettings.HeavyClass[combatPlayer.currentclass];

                    // Check if the damage is from a bullet
                    if (hitInfo.damageTypes.Has(DamageType.Bullet))
                    {
                        float damageReduction = (float)heavySettings.bulletdmgreduction;
                        ApplySpecificDamageReduction(hitInfo, DamageType.Bullet, damageReduction);
                    }
                    // SkillTree owns explosive resistance — skip heavy explosivedmgreduction when 0 / disabled.
                    if (heavySettings.explosivedmgreduction != 0 && hitInfo.damageTypes.Has(DamageType.Explosion))
                    {
                        float damageReduction = (float)heavySettings.explosivedmgreduction;
                        ApplySpecificDamageReduction(hitInfo, DamageType.Explosion, damageReduction);
                    }
                    break;
            }
        }
        private void ApplySpecificDamageReduction(HitInfo hitInfo, DamageType damageType, float damageReduction)
        {
            try
            {
                float currentDamage = hitInfo.damageTypes.Get(damageType);
                if (currentDamage > 0)
                {
                    float newDamage = currentDamage * (1 - damageReduction);
                    hitInfo.damageTypes.Set(damageType, newDamage);
                }
            }
            catch (IndexOutOfRangeException ex)
            {
                Puts($"Error applying specific damage reduction for damage type {damageType}: {ex.Message}");
            }
        }
        private void HandleGrenadeDeployment(InputState input, BasePlayer player, ulong playerId, float deployTimer, Dictionary<ulong, DateTime?> deployTimes, string grenadeName, Action<BasePlayer> throwGrenadeAction)
        {
            if (input.IsDown(BUTTON.RELOAD))
            {
                if (reloadStartTimes[playerId] == null)
                {
                    reloadStartTimes[playerId] = DateTime.Now;
                    player.ChatMessage($"<color=#FFA500>Preparing {grenadeName}... Hold RELOAD for 3 seconds</color>");
                }
                else
                {
                    double holdTime = (DateTime.Now - reloadStartTimes[playerId].Value).TotalSeconds;
                    
                    // Show countdown every second
                    int secondsHeld = (int)holdTime;
                    if (secondsHeld > 0 && secondsHeld < 3 && (holdTime - secondsHeld) < 0.1)
                    {
                        int remaining = 3 - secondsHeld;
                        player.ChatMessage($"<color=#FFA500>Hold for {remaining} more second{(remaining > 1 ? "s" : "")}...</color>");
                    }
                    
                    if (holdTime >= 3)
                    {
                        // Check cooldown timer
                        if (deployTimes[playerId] == null || (DateTime.Now - deployTimes[playerId].Value).TotalSeconds >= deployTimer)
                        {
                            // Throw the grenade
                            throwGrenadeAction(player);
                            deployTimes[playerId] = DateTime.Now;
                            player.ChatMessage($"<color=#00FF00>{grenadeName} thrown!</color>");
                        }
                        else
                        {
                            player.ChatMessage(CCLang("throwablecooldown", player.UserIDString, Math.Round(deployTimer - (DateTime.Now - deployTimes[playerId].Value).TotalSeconds), grenadeName));
                        }

                        // Reset the reload start time
                        reloadStartTimes[playerId] = null;
                    }
                }
            }
            else
            {
                // Reset the reload start time if the reload button is released
                if (reloadStartTimes[playerId] != null)
                {
                    double holdTime = (DateTime.Now - reloadStartTimes[playerId].Value).TotalSeconds;
                    if (holdTime < 3)
                    {
                        player.ChatMessage($"<color=#FF0000>Release too early! Hold RELOAD for 3 seconds to throw {grenadeName}</color>");
                    }
                    reloadStartTimes[playerId] = null;
                }
            }
        }
        private void ThrowSmokeGrenade(BasePlayer player)
        {
            // Logic to throw a smoke grenade in the direction the player is looking
            Vector3 forward = player.eyes.BodyForward();
            Vector3 startPos = player.eyes.position; // Use eye position for more accurate throwing
            Vector3 throwDirection = (forward + Vector3.up * 0.2f).normalized * 15f; // Add slight upward arc and normalize

            BaseEntity smokeGrenade = GameManager.server.CreateEntity("assets/prefabs/tools/smoke grenade/grenade.smoke.deployed.prefab", startPos, Quaternion.LookRotation(Vector3.up));
            if (smokeGrenade != null)
            {
                smokeGrenade.creatorEntity = player;
                smokeGrenade.SetVelocity(throwDirection);
                smokeGrenade.Spawn();
            }
            else
            {
                player.ChatMessage("<color=#FF0000>Failed to create smoke grenade!</color>");
            }
        }
        private void ThrowGrenade(BasePlayer player)
        {
            // Logic to throw a regular grenade in the direction the player is looking
            Vector3 forward = player.eyes.BodyForward();
            Vector3 startPos = player.transform.position + Vector3.up * 1.5f; // Adjust start position if necessary
            Vector3 throwDirection = forward * 15f; // Adjust throw force if necessary

            BaseEntity grenade = GameManager.server.CreateEntity("assets/prefabs/weapons/f1 grenade/grenade.f1.deployed.prefab", startPos, Quaternion.identity);
            if (grenade != null)
            {
                grenade.SetVelocity(throwDirection);
                grenade.Spawn();
            }
        }
