        // Deaths & Kills
        #region Deaths & Kills
        private void HandleDeaths(BasePlayer victim, HitInfo hitInfo)
        {
            if (!victim.userID.Get().IsSteamId()) return;

            CombatPlayer combatPlayer = GetCombatPlayer(victim);
            if (combatPlayer == null) return;

            var combatClass = GetClassData(combatPlayer.currentclass);
            if (combatClass == null) return;

            // If the victim committed suicide
            if (victim == hitInfo.Initiator)
            {
                combatPlayer.suicides++;
            }
            else
            {
                // Track deaths
                combatPlayer.deaths++;
                if(config.mainSettings.canchangeclassondeath)
                {
                    // Convert the seconds into a TimeSpan
                    TimeSpan classChangeTimeSpan = TimeSpan.FromSeconds(config.mainSettings.classchangetimer);

                    // Subtract the TimeSpan from the player's last class change time
                    DateTime newClassChangeTime = combatPlayer.classchange - classChangeTimeSpan;
                }
            }

            // Track the death for the player's current class
            // If the victim committed suicide
            if (victim == hitInfo.Initiator)
            {
                combatPlayer.combatclass[combatPlayer.currentclass].suicides++;
            }
            else
            {
                // Track deaths
                combatPlayer.combatclass[combatPlayer.currentclass].deaths++;
            }
        }
        private void HandleKills(BasePlayer attacker, BaseCombatEntity entity, HitInfo hitInfo)
        {
            if (!attacker.userID.Get().IsSteamId()) return;
            CombatPlayer combatPlayer = GetCombatPlayer(attacker);
            if (combatPlayer == null) return;

            // Ignore Suicide
            if(attacker == entity) return;
            
            bool isValidKill = false;

            // Track kills
            if (entity is BasePlayer)
            {
                var playerKill = entity as BasePlayer;
                if (playerKill.userID.Get().IsSteamId())
                {
                    combatPlayer.playerkills++;
                    isValidKill = true;
                }
                if (IsValidNPC(entity))
                {
                    combatPlayer.npckills++;
                    isValidKill = true;
                }
            }
            else
            {
                if (IsValidNPC(entity))
                {
                    combatPlayer.npckills++;
                    isValidKill = true;
                }
            }

            if (!isValidKill) return;

            // Track the kill for the player's current class
            if (entity is BasePlayer)
            {
                var playerKill = entity as BasePlayer;
                if (playerKill.userID.Get().IsSteamId())
                {
                    combatPlayer.combatclass[combatPlayer.currentclass].playerkills++;
                    GiveXP(attacker, config.mainSettings.playerkillxp);
                }
                if (IsValidNPC(entity))
                {
                    combatPlayer.combatclass[combatPlayer.currentclass].npckills++;
                    int xp = GetNPCXP(entity);
                    GiveXP(attacker, xp);
                }
            }
            else
            {
                combatPlayer.combatclass[combatPlayer.currentclass].npckills++;
                int xp = GetNPCXP(entity);
                GiveXP(attacker, xp);
            }

            if (config.mainSettings.showkills)
            {
                string attackerName = GetNameBE(hitInfo.Initiator);
                string victimName = GetNameBCE(entity);
                GlobalKillNotice(attackerName, victimName);
            }
        }
