        // Assassin
        #region Assassin
        private Dictionary<ulong, Timer> pingTimers = new Dictionary<ulong, Timer>();
        private void AssassinDetection(BasePlayer player)
        {
            if (player == null || !player.IsConnected || !player.userID.IsSteamId()) return;

            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null || combatPlayer.currentclass != "assassin") return;

            var combatClass = GetClassData(combatPlayer.currentclass);
            if (combatClass == null) return;

            var assassinSettings = combatClass as AssassinSettings;
            if (assassinSettings == null) return;

            // Cancel any existing ping timer for this player
            if (pingTimers.ContainsKey(player.userID) && pingTimers[player.userID] != null)
            {
                pingTimers[player.userID].Destroy();
                pingTimers[player.userID] = null;
            }

            Vector3 playerPosition = player.ServerPosition;

            var alertCheck = new List<string> { "player", "scientist", "dweller", "scarecrow", "zombie" };
            var alertsList = Facepunch.Pool.Get<List<BaseEntity>>();
            Vis.Entities(player.ServerPosition, assassinSettings.pingdistance, alertsList);

            double alertDistanceLimit = assassinSettings.pingdistance + (assassinSettings.pingdistance * (assassinSettings.pingdistanceinc * combatPlayer.combatclass["assassin"].level));
            string alertName = string.Empty;
            bool sendAlert = false;

            foreach (var alert in alertsList)
            {
                if (alert == null || alert == player) continue;

                // Player Detection
                if (alert is BasePlayer)
                {
                    var alertPlayer = alert as BasePlayer;
                    if (config.classSettings.AssassinClass["assassin"].ignoresleepers && alertPlayer.IsSleeping()) continue;
                    if (config.classSettings.AssassinClass["assassin"].targetidentify && combatPlayer.combatclass["assassin"].level >= config.classSettings.AssassinClass["assassin"].targetidentifylevel)
                    {
                        alertName = alertPlayer.ToPlayer().displayName;
                    }
                    if (Vector3.Distance(playerPosition, alert.ServerPosition) <= alertDistanceLimit) sendAlert = true;
                }
                foreach (var checkEntity in alertCheck)
                {
                    if (alert.ShortPrefabName.Contains(checkEntity))
                    {
                        sendAlert = true;
                    }
                }
                if (sendAlert)
                {
                    player.RunEffect(alert.ServerPosition, "assets/prefabs/locks/keypad/effects/lock.code.unlock.prefab");

                    double dangerDistance = Math.Round(Vector3.Distance(playerPosition, alert.ServerPosition));

                    // Send a message to the player
                    if (!string.IsNullOrEmpty(alertName))
                    {
                        player.ChatMessage($"{CCLang("CC_assassin_005", player.UserIDString, alertName, dangerDistance)}");
                    }
                    else
                    {
                        player.ChatMessage($"{CCLang("CC_assassin_004", player.UserIDString, dangerDistance)}");
                    }
                }
            }

            // Start a new timer for passive detection
            pingTimers[player.userID] = timer.Once(assassinSettings.pingtimer, () =>
            {
                AssassinDetection(player);
            });
            Facepunch.Pool.FreeUnmanaged<BaseEntity>(ref alertsList);
        }
        private bool IsMeleeWeapon(string weaponShortName)
        {
            string[] meleeWeapons = { "sword", "knife", "pickaxe", "axe", "machete"};
            foreach (string weapon in meleeWeapons)
            {
                if (!weaponShortName.Contains(weaponShortName)) continue;
                return true;
            }
            return false;
        }
        private void ApplyMeleeDamageBonus(AssassinSettings settings, string weaponShortName, HitInfo hitInfo)
        {
            if (IsMeleeWeapon(weaponShortName))
            {
                // Apply melee damage bonus
                float meleeDamageBonus = (float)(settings.meleedmgincrease * hitInfo.damageTypes.Total());
                //hitInfo.damageTypes.ScaleAll(1 + meleeDamageBonus);
                hitInfo.damageTypes.Add(DamageType.Generic, meleeDamageBonus);
                // Apply poison effect
                ApplyPoisonEffect(hitInfo, settings.poisonmeleeamount, settings.poisonmeleeinc, settings.poisonmeleeduration);
            }
        }
        private void ApplyPoisonEffect(HitInfo hitInfo, float poisonDamage, float poisonInc, float poisonDuration)
        {
            BasePlayer target = hitInfo.HitEntity as BasePlayer;
            if (target == null) return;

            BasePlayer assassin = hitInfo.Initiator as BasePlayer;
            if (assassin == null) return;

            CombatPlayer combatPlayer = GetCombatPlayer(assassin);
            if (combatPlayer == null) return;

            var assassinclass = combatPlayer.combatclass["assassin"];
            // Adjust values based on Assassin level
            poisonDuration += (float)Math.Round(poisonDuration * (.01 * assassinclass.level), 2);
            poisonDamage += (float)Math.Round(poisonDamage * (0.1 * assassinclass.level), 2);

            // Apply damage over time
            target.InvokeRepeating(() => PoisonDamageTick(target, poisonDamage), 1f, poisonInc);
            target.Invoke(() => StopPoisonEffect(target), poisonDuration);
        }
        private void PoisonDamageTick(BasePlayer target, float poisonDamage)
        {
            if (target == null || target.IsDead()) return;

            // Apply poison damage
            target.Hurt(poisonDamage, DamageType.Poison);
        }
        private void StopPoisonEffect(BasePlayer target)
        {
            if (target == null) return;

            // Stop applying poison damage
            target.CancelInvoke(nameof(PoisonDamageTick));
        }
        private void ClearAllEffects(BasePlayer player)
        {
            if (player == null) return;

            // Ensure all potential invocations are cancelled
            player.InvokeRepeating(() => PoisonDamageTick(player, 0), 1f, 1f); // Temporary invocation with 0 damage
            player.InvokeRepeating(() => StopPoisonEffect(player), 1f, 1f); // Temporary invocation

            // Cancel all poison-related invocations
            player.CancelInvoke(nameof(PoisonDamageTick));
            player.CancelInvoke(nameof(StopPoisonEffect));
            player.CancelInvoke();
        }
        #endregion

        // Sniper
        #region Sniper
        private void HandleSniperScan(InputState input, BasePlayer player, ulong playerId, float deployTimer, Dictionary<ulong, DateTime?> deployTimes)
        {
            if (input.IsDown(BUTTON.RELOAD))
            {
                if (reloadStartTimes[playerId] == null)
                {
                    reloadStartTimes[playerId] = DateTime.Now;
                }
                else if ((DateTime.Now - reloadStartTimes[playerId].Value).TotalSeconds >= 3)
                {
                    // Check cooldown timer
                    if (deployTimes[playerId] == null || (DateTime.Now - deployTimes[playerId].Value).TotalSeconds >= deployTimer)
                    {
                        // Highlight Targets
                        HighlightSniperTargets(player);
                        deployTimes[playerId] = DateTime.Now;
                    }
                    else
                    {
                        player.ChatMessage(CCLang("scancooldown", player.UserIDString, Math.Round(deployTimer - (DateTime.Now - deployTimes[playerId].Value).TotalSeconds)));
                    }

                    // Reset the reload start time
                    reloadStartTimes[playerId] = null;
                }
            }
            else
            {
                // Reset the reload start time if the reload button is released
                reloadStartTimes[playerId] = null;
            }
        }
        private void HighlightSniperTargets(BasePlayer sniper)
        {
            if (sniper == null || !sniper.userID.IsSteamId()) return;

            CombatPlayer combatPlayer = GetCombatPlayer(sniper);
            if (combatPlayer == null) return;

            var combatClass = GetClassData(combatPlayer.currentclass);
            if (combatClass == null) return;

            var sniperSettings = combatClass as SniperSettings;
            if (sniperSettings == null) return;

            float sniperDistance = sniperSettings.scandistance + (float)(sniperSettings.scaninc * combatPlayer.combatclass["sniper"].level);
            float sniperDuration = sniperSettings.scanduration + (float)(sniperSettings.scaninc * combatPlayer.combatclass["sniper"].level);

            Vector3 sniperPosition = sniper.ServerPosition;
            var targetCheck = new List<string> { "player", "scientist", "dweller", "scarecrow", "zombie" };
            var targets = Facepunch.Pool.Get<List<BaseEntity>>();
            Vis.Entities(sniperPosition, sniperDistance, targets); // Adjust the range as needed

            foreach (var target in targets)
            {
                bool HighLight = false;
                if (target == sniper) continue;
                bool isSleeping = false;
                if (target.ToPlayer() != null)
                {
                    isSleeping = target.ToPlayer().IsSleeping();
                    if (isSleeping && !sniperSettings.scansleepers) continue;
                }
                foreach (var checkEntity in targetCheck)
                {
                    if (target.ShortPrefabName.Contains(checkEntity))
                    {
                        HighLight = true;
                        break;
                    }
                }

                if (HighLight)
                {
                    BasePlayer targetPlayer = target as BasePlayer;
                    bool isSameTeam = targetPlayer != null && sniper != null && ArePlayersOnSameTeam(sniper, targetPlayer);
                    AttachLightToTarget(target, sniperDuration, isSameTeam, isSleeping);
                }
            }
            Facepunch.Pool.FreeUnmanaged<BaseEntity>(ref targets);
        }
        private bool ArePlayersOnSameTeam(BasePlayer player1, BasePlayer player2)
        {
            return player1.Team != null && player2.Team != null && player1.Team == player2.Team;
        }
        private void AttachLightToTarget(BaseEntity target, float duration, bool isSameTeam, bool isSleeping)
        {
            if (target == null) return;

            string lightPrefab = isSameTeam ? "assets/prefabs/misc/permstore/industriallight/industrial.wall.lamp.green.deployed.prefab" : "assets/prefabs/misc/permstore/industriallight/industrial.wall.lamp.red.deployed.prefab";
            lightPrefab = isSleeping ? "assets/prefabs/misc/permstore/industriallight/industrial.wall.lamp.deployed.prefab" : lightPrefab;

            // Spawn the light above the target's head
            var light = GameManager.server.CreateEntity(lightPrefab, target.transform.position + new Vector3(0, 2, 0), Quaternion.identity);
            if (light != null)
            {
                // Ensure the light is turned on
                var electricLight = light.GetComponent<IOEntity>();
                if (electricLight != null)
                {
                    electricLight.SetFlag(BaseEntity.Flags.On, true);
                    electricLight.SendNetworkUpdateImmediate();
                }

                light.Spawn();

                // Ensure the light follows the target
                timer.Repeat(0.1f, (int)(duration / 0.1f), () =>
                {
                    if (target != null && light != null)
                    {
                        light.transform.position = target.transform.position + new Vector3(0, 2, 0);
                    }
                });

                // Destroy the light after the specified duration
                timer.Once(duration, () => light.Kill());
            }
        }
        #endregion

        // Scavenger
        #region Scavenger
        private Dictionary<ulong, DateTime?> lastScavengerTapReadyTimes = new Dictionary<ulong, DateTime?>();
        private Dictionary<ulong, DateTime?> scavengerReloadHoldStart = new Dictionary<ulong, DateTime?>();

        private void HandleScavengerTapReady(InputState input, BasePlayer player, ulong playerId, ScavengerSettings settings)
        {
            if (input.IsDown(BUTTON.RELOAD))
            {
                if (!scavengerReloadHoldStart.ContainsKey(playerId) || scavengerReloadHoldStart[playerId] == null)
                {
                    scavengerReloadHoldStart[playerId] = DateTime.Now;
                }
                else if ((DateTime.Now - scavengerReloadHoldStart[playerId].Value).TotalSeconds >= settings.tapreadyholdtime)
                {
                    // cooldown window randomized between min and max (30 sec - 3 min)
                    if (!lastScavengerTapReadyTimes.ContainsKey(playerId)) lastScavengerTapReadyTimes[playerId] = null;
                    int cooldown = UnityEngine.Random.Range(settings.tapreadycooldown, settings.tapreadymaxcooldown + 1);

                    if (lastScavengerTapReadyTimes[playerId] == null || (DateTime.Now - lastScavengerTapReadyTimes[playerId].Value).TotalSeconds >= cooldown)
                    {
                        EnableEokaTapOnce(player);
                        lastScavengerTapReadyTimes[playerId] = DateTime.Now;
                    }
                    else
                    {
                        double remain = Math.Max(0, cooldown - (DateTime.Now - lastScavengerTapReadyTimes[playerId].Value).TotalSeconds);
                        player.ChatMessage($"Tap Ready on cooldown: {Math.Round(remain)}s");
                    }

                    scavengerReloadHoldStart[playerId] = null;
                }
            }
            else
            {
                scavengerReloadHoldStart[playerId] = null;
            }
        }

        private void EnableEokaTapOnce(BasePlayer player)
        {
            var active = player.GetActiveItem();
            if (active == null || active.info == null) return;
            if (active.info.shortname != "pistol.eoka")
            {
                player.ChatMessage("Hold Eoka to arm Tap Ready.");
                return;
            }

            var projectile = active.GetHeldEntity() as BaseProjectile;
            if (projectile == null) return;
            var flint = projectile as FlintStrikeWeapon;
            if (flint == null)
            {
                // Try finding a FlintStrikeWeapon on the entity
                flint = projectile.GetComponent<FlintStrikeWeapon>();
            }
            if (flint == null) return;

            float originalSuccess = flint.successFraction;
            flint.successFraction = 1f;
            player.ChatMessage("Tap Ready: next Eoka strike guaranteed.");

            // Revert after one shot or 10 seconds if unused
            Action revert = () => { if (flint != null) flint.successFraction = originalSuccess; };
            projectile.Invoke(revert, 10f);

            // Also hook OnProjectileFired-like event via timer to check ammo consumed; fallback single-shot revert
        }
