        private void DebugImg(string message)
        {
            if (config == null || config.imageSettings == null || !config.imageSettings.debugImages)
                return;

            Puts(message);
        }

        private void LoadImages(bool forcereload = false)
        {
            _CCImageList = new Dictionary<string, uint>();
            
            try
            {
                var imagesDir = ResolveAssetDirectory("images");
                if (!System.IO.Directory.Exists(imagesDir))
                {
                    Puts($"[IMG] Local images directory not found. Tried oxide/data and {CombatClassesDataRoot}. Last: {imagesDir}");
                    return;
                }
                Puts($"[IMG] Loading CombatClasses images from: {imagesDir}");

                var files = System.IO.Directory.EnumerateFiles(imagesDir, "*", System.IO.SearchOption.TopDirectoryOnly)
                .Where(p => {
                    var ext = System.IO.Path.GetExtension(p);
                    return string.Equals(ext, ".png", StringComparison.OrdinalIgnoreCase) || 
                           string.Equals(ext, ".jpg", StringComparison.OrdinalIgnoreCase) ||
                           string.Equals(ext, ".jpeg", StringComparison.OrdinalIgnoreCase);
                })
                .ToArray();
                if (files == null || files.Length == 0)
                {
                    DebugImg("[IMG] No local images found to register.");
                    return;
                }

                int registered = 0;
                foreach (var file in files)
                {
                    var name = System.IO.Path.GetFileNameWithoutExtension(file);
                    if (string.IsNullOrEmpty(name)) continue;

                    var bytes = System.IO.File.ReadAllBytes(file);
                    var ownerIdNullable = CommunityEntity.ServerInstance?.net?.ID;
                    var owner = ownerIdNullable ?? default(NetworkableId);
                    if (owner == default(NetworkableId))
                    {
                        DebugImg("[IMG] CommunityEntity.ServerInstance not ready; skipping local image registration.");
                        continue;
                    }

                    var ext = System.IO.Path.GetExtension(file).ToLower();
                    var fileType = ext == ".png" ? FileStorage.Type.png : FileStorage.Type.jpg;
                    var id = FileStorage.server.Store(bytes, fileType, owner);
                    if (id != 0)
                    {
                        // Register with simple name
                        _CCImageList[name] = id;
                        
                        // Also register with CC prefix for compatibility
                        _CCImageList["CC" + name] = id;
                        
                        registered++;
                    }
                }
                if (registered > 0)
                    DebugImg($"[IMG] Successfully loaded {registered} CombatClasses images");
                
                // Load existing Steam avatars
                LoadSteamAvatars();
            }
            catch (Exception ex)
            {
                DebugImg($"[IMG] Failed to auto-register local images: {ex.Message}");
            }
        }
        
        private void LoadSteamAvatars()
        {
            string avatarDir = ResolveAssetDirectory("Avatars");
            if (!System.IO.Directory.Exists(avatarDir))
            {
                return;
            }
            
            var avatarFiles = System.IO.Directory.GetFiles(avatarDir, "*.png", System.IO.SearchOption.TopDirectoryOnly);
            int loadedCount = 0;
            
            foreach (string filePath in avatarFiles)
            {
                try
                {
                    string fileName = System.IO.Path.GetFileNameWithoutExtension(filePath);
                    if (string.IsNullOrEmpty(fileName) || !ulong.TryParse(fileName, out _)) continue;
                    
                    byte[] imageBytes = System.IO.File.ReadAllBytes(filePath);
                    var ownerId = CommunityEntity.ServerInstance?.net?.ID ?? default(NetworkableId);
                    if (ownerId != default(NetworkableId))
                    {
                        var id = FileStorage.server.Store(imageBytes, FileStorage.Type.png, ownerId);
                        if (id != 0)
                        {
                            _CCImageList[fileName] = id;
                            loadedCount++;
                        }
                    }
                }
                catch (Exception ex)
                {
                    DebugImg($"[IMG] Failed to load Steam avatar {filePath}: {ex.Message}");
                }
            }
            
            if (loadedCount > 0)
            {
                DebugImg($"[IMG] Loaded {loadedCount} existing Steam avatars");
            }
        }
        
        private bool RegisterLocalImageKey(string key, out uint id)
        {
            id = 0;
            try
            {
                if (string.IsNullOrEmpty(key)) return false;
                if (_CCImageList.TryGetValue(key, out id) && id != 0) return true;

                var imagesDir = ResolveAssetDirectory("images");
                if (!System.IO.Directory.Exists(imagesDir)) return false;

                var imagePath = System.IO.Path.Combine(imagesDir, key + ".png");
                var fileType = FileStorage.Type.png;
                if (!System.IO.File.Exists(imagePath))
                {
                    imagePath = System.IO.Path.Combine(imagesDir, key + ".jpg");
                    fileType = FileStorage.Type.jpg;
                    if (!System.IO.File.Exists(imagePath)) return false;
                }

                var bytes = System.IO.File.ReadAllBytes(imagePath);
                var ownerIdNullable = CommunityEntity.ServerInstance?.net?.ID;
                var owner = ownerIdNullable ?? default(NetworkableId);
                if (owner == default(NetworkableId)) return false;

                id = FileStorage.server.Store(bytes, fileType, owner);
                if (id == 0) return false;

                _CCImageList[key] = id;
                _CCImageList["CC" + key] = id;
                return true;
            }
            catch (Exception ex)
            {
                PrintWarning($"Failed to load image '{key}': {ex.Message}");
                id = 0;
                return false;
            }
        }
        
        private uint GetImage(string fileName)
        {
            // Try the exact key first
            if (_CCImageList.TryGetValue(fileName, out var imageId))
                return imageId;
            
            // Handle theme-based image mapping (CCmbg5 -> box5, CCbg3 -> bg3, CCbg1 -> bg1, CCbg -> bg).
            if (fileName.StartsWith("CCmbg"))
            {
                var themeNumber = fileName.Length > 5 ? fileName.Substring(5) : "";
                var mappedKey = string.IsNullOrEmpty(themeNumber) || themeNumber == "0" ? "box" : "box" + themeNumber;
                if (_CCImageList.TryGetValue(mappedKey, out imageId))
                    return imageId;
            }
            else if (fileName.StartsWith("CCbg"))
            {
                var themeNumber = fileName.Length > 4 ? fileName.Substring(4) : "";
                var mappedKey = string.IsNullOrEmpty(themeNumber) || themeNumber == "0" ? "bg" : "bg" + themeNumber;
                if (_CCImageList.TryGetValue(mappedKey, out imageId))
                    return imageId;
            }
            else if (fileName.StartsWith("CCTheme") && fileName.Length > 7)
            {
                var themeNumber = fileName.Substring(7);
                var mappedKey = "theme" + themeNumber;
                if (_CCImageList.TryGetValue(mappedKey, out imageId))
                    return imageId;
            }
            else if (fileName.StartsWith("CCbutton") && fileName.Length > 8)
            {
                var themeNumber = fileName.Substring(8);
                var mappedKey = "button" + themeNumber;
                if (_CCImageList.TryGetValue(mappedKey, out imageId))
                    return imageId;
            }
            
            // Try without CC prefix (e.g., "CCassault" -> "assault")
            if (fileName.StartsWith("CC") && fileName.Length > 2)
            {
                var simpleKey = fileName.Substring(2).ToLower();
                if (_CCImageList.TryGetValue(simpleKey, out imageId))
                    return imageId;
            }
            
            // Try with CC prefix (e.g., "assault" -> "CCassault")
            var ccKey = "CC" + fileName;
            if (_CCImageList.TryGetValue(ccKey, out imageId))
                return imageId;
            
            // Handle player avatars - try to fetch Steam avatar
            if (ulong.TryParse(fileName, out var steamId))
            {
                DebugImg($"[IMG] Requesting avatar for Steam ID: {fileName}");
                
                // Check if we already have this player's avatar
                if (_CCImageList.TryGetValue(fileName, out imageId))
                {
                    DebugImg($"[IMG] Found cached avatar for {fileName}: {imageId}");
                    return imageId;
                }
                
                // Try to fetch Steam avatar
                DebugImg($"[IMG] Fetching avatar for {fileName}");
                FetchSteamAvatar(steamId);
                
                // Check again after fetching
                if (_CCImageList.TryGetValue(fileName, out imageId))
                {
                    DebugImg($"[IMG] Found avatar after fetch for {fileName}: {imageId}");
                    return imageId;
                }
                
                // Return default icon as fallback
                if (_CCImageList.TryGetValue("icon", out imageId))
                {
                    DebugImg($"[IMG] Using fallback icon for {fileName}: {imageId}");
                    return imageId;
                }
                return 0;
            }
            
            // Debug: Log missing images
            if (imageId == 0)
            {
                DebugImg($"[IMG] Missing image: '{fileName}' - Available keys: {string.Join(", ", _CCImageList.Keys.Take(10))}...");
            }
            
            return 0;
        }
        
        private void FetchSteamAvatar(ulong steamId)
        {
            // Don't fetch if we already have this avatar
            if (_CCImageList.ContainsKey(steamId.ToString()))
                return;
                
            // Only fetch if we have a Steam API key configured
            if (string.IsNullOrEmpty(config.imageSettings.steamApiKey))
            {
                // Fallback to default icon if no API key
                if (_CCImageList.TryGetValue("icon", out var iconId))
                {
                    _CCImageList[steamId.ToString()] = iconId;
                    DebugImg($"[IMG] Using default icon for Steam avatar of player {steamId} (no API key)");
                }
                return;
            }
                
            // Use the same method as ImageLibrary
            string steamApiUrl = $"https://api.steampowered.com/ISteamUser/GetPlayerSummaries/v0002/?key={config.imageSettings.steamApiKey}&steamids={steamId}";
            
            webrequest.Enqueue(steamApiUrl, null, (code, response) =>
            {
                if (response != null && code == 200)
                {
                    try
                    {
                        var avatarData = Newtonsoft.Json.JsonConvert.DeserializeObject<SteamAvatarResponse>(response);
                        if (avatarData?.response?.players?.Length > 0)
                        {
                            string avatarUrl = avatarData.response.players[0].avatarmedium;
                            if (!string.IsNullOrEmpty(avatarUrl))
                            {
                                // Download and store the Steam avatar using ImageLibrary's method
                                DownloadAndStoreSteamAvatar(steamId.ToString(), avatarUrl);
                            }
                            else
                            {
                                // Fallback to default icon
                                if (_CCImageList.TryGetValue("icon", out var iconId))
                                {
                                    _CCImageList[steamId.ToString()] = iconId;
                                    DebugImg($"[IMG] Using default icon for Steam avatar of player {steamId} (no avatar URL)");
                                }
                            }
                        }
                        else
                        {
                            // Fallback to default icon
                            if (_CCImageList.TryGetValue("icon", out var iconId))
                            {
                                _CCImageList[steamId.ToString()] = iconId;
                                DebugImg($"[IMG] Using default icon for Steam avatar of player {steamId} (no player data)");
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        DebugImg($"[IMG] Failed to parse Steam avatar response: {ex.Message}");
                        // Fallback to default icon
                        if (_CCImageList.TryGetValue("icon", out var iconId))
                        {
                            _CCImageList[steamId.ToString()] = iconId;
                        }
                    }
                }
                else
                {
                    // Fallback to default icon on failure
                    if (_CCImageList.TryGetValue("icon", out var iconId))
                    {
                        _CCImageList[steamId.ToString()] = iconId;
                        DebugImg($"[IMG] Using default icon for Steam avatar of player {steamId} (API request failed)");
                    }
                }
            }, this);
        }
        
        private void DownloadAndStoreSteamAvatar(string steamId, string avatarUrl)
        {
            // Create the avatars directory if it doesn't exist
            // Prefer oxide/data Avatars (same folder as UI images); create under CombatClassesDataRoot if missing.
            string avatarDir = ResolveAssetDirectory("Avatars");
            if (!System.IO.Directory.Exists(avatarDir))
            {
                avatarDir = Path.Combine(OxideCombatClassesDir, "Avatars");
                System.IO.Directory.CreateDirectory(avatarDir);
            }
            
            // Use a different approach - download the image directly using System.Net.WebClient
            try
            {
                using (var webClient = new System.Net.WebClient())
                {
                    string avatarPath = $"{avatarDir}/{steamId}.png";
                    webClient.DownloadFile(avatarUrl, avatarPath);
                    
                    // Load the image into Rust's FileStorage system
                    var ownerId = CommunityEntity.ServerInstance?.net?.ID ?? default(NetworkableId);
                    if (ownerId != default(NetworkableId))
                    {
                        var imageBytes = System.IO.File.ReadAllBytes(avatarPath);
                        var id = FileStorage.server.Store(imageBytes, FileStorage.Type.png, ownerId);
                        if (id != 0)
                        {
                            _CCImageList[steamId] = id;
                            DebugImg($"[IMG] Successfully downloaded and stored Steam avatar for player {steamId} at {avatarPath}");
                        }
                        else
                        {
                            // Fallback to default icon
                            if (_CCImageList.TryGetValue("icon", out var iconId))
                            {
                                _CCImageList[steamId] = iconId;
                                DebugImg($"[IMG] Using default icon for Steam avatar of player {steamId} (storage failed)");
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                DebugImg($"[IMG] Failed to download Steam avatar: {ex.Message}");
                // Fallback to default icon
                if (_CCImageList.TryGetValue("icon", out var iconId))
                {
                    _CCImageList[steamId] = iconId;
                }
            }
        }
