        #region UI Panel Helpers
        public float CalculateAnchorMin(int numberOfValues)
        {
            return 1f - (numberOfValues * .1f);
        }
        public CuiElement UIScroll(string parent, string anchorMin = "0 0", string anchorMax = "1 1", string handleColor = "0 0 0 0", int numberOfValues = 0)
        {
            string scrollAnchorMin = "0 0";
            string scrollAnchorMax = "1 1";
            float value = CalculateAnchorMin(numberOfValues);
            if (value < 0f)
            {
                // Extend content height while keeping viewport anchors unchanged
                scrollAnchorMin = $"0 {value}";
            }

            return new CuiElement
            {
                Parent = parent,
                Name = CC_ScrollView,
                Components =
                {
                    new CuiRectTransformComponent
                    {
                        AnchorMin = anchorMin,
                        AnchorMax = anchorMax
                    },
                    new CuiScrollViewComponent
                    {
                        ContentTransform = new CuiRectTransform
                        {
                            AnchorMin = scrollAnchorMin,
                            AnchorMax = scrollAnchorMax
                        },
                        Horizontal = false,
                        Vertical = true,
                        ScrollSensitivity = 0.1f
                    }
                }
            };
        }
        public CuiLabel UILabel(string text, int i, float height, TextAnchor align = TextAnchor.MiddleLeft, int fontSize = 13, string xMin = "0", string xMax = "1", string color = "1 1 1 1")
        {
            return new CuiLabel
            {
                RectTransform =
                {
                    AnchorMin = $"{xMin} {1 - height*i + i * .002f}",
                    AnchorMax = $"{xMax} {1 - height*(i-1) + i * .002f}"
                },
                Text =
                {
                    Text = text,
                    FontSize = fontSize,
                    Align = align,
                    Color = color
                }
