        private void UseCustomTheme()
        {
            string custompath = config.imageSettings.customfolder;
            if (custompath == string.Empty || !Directory.Exists($"{config.imageSettings.localpath}/{custompath}"))
            {
                Puts("Custom Folder not found, check folder name and location");
                return;
            }
            Puts("Switching to custom theme directory... \n");
            
            // Update the localpath to point to the custom folder
            string originalPath = config.imageSettings.localpath;
            config.imageSettings.localpath = $"{config.imageSettings.localpath}/{custompath}";
            
            // Reload images from the custom directory
            LoadImages(true);
            
            // Restore original path
            config.imageSettings.localpath = originalPath;
            
            Puts("Custom theme loaded successfully!");
        }
