        private void CCDmgIndicator(BasePlayer player, double dmgamount)
        {
            if (player == null || dmgamount == 0 || !player.userID.Get().IsSteamId()) return;

            string uiName = $"DamageIndicator_{player.userID}";

            CuiHelper.DestroyUi(player, uiName);

            // Create and show the UI
            string uiElement = CreateDamageUI(dmgamount.ToString(), uiName);
            CuiHelper.AddUi(player, uiElement);

            // Remove the UI after 2 seconds
            timer.Once(2f, () => CuiHelper.DestroyUi(player, uiName));
        }
        private string CreateDamageUI(string damageText, string uiName)
