        public string ThemeColor(BasePlayer player, string type, double tone = .5)
        {
            if (player == null || !player.userID.Get().IsSteamId()) return string.Empty;

            Themes themes = GetPlayerTheme(player);
            string hex = string.Empty;
            string cui = string.Empty;

            switch (themes.theme)
            {
                case 0:
                case 1:
                    hex = "#FFFFFF";
                    cui = $".5 .5 .5 {tone}";
                    break;
                case 2:
                    hex = "#FF0000";
                    cui = $".5 0 0 {tone}";
                    break;
                case 3:
                    hex = "#0000FF";
                    cui = $"0 0 .5 {tone}";
                    break;
                case 4:
                    hex = "#00FF00";
                    cui = $"0 .5 0 {tone}";
                    break;
                case 5:
                    hex = "#bf00ff";
                    cui = $".75 0 1 {tone}";
                    break;
            }

            return type switch
            {
                "hex" => hex,
                "cui" => cui,
                _ => string.Empty,
            };
        }
