        private void GiveCombatGearBox(BasePlayer player, string command, string[] args)
        {
            if (player == null || !player.userID.Get().IsSteamId() || !player.IsAdmin) return;
            int amount = 1;
            if(args.Length > 0)
            {
                amount = Convert.ToInt32(args[0]);
            }
            Item createitem = ItemManager.CreateByItemID(833533164, amount, config.gearBox.SkinID);
            createitem.name = config.gearBox.DisplayName;
            createitem.info.name = config.gearBox.DisplayName;
            createitem.MarkDirty();
            if (createitem == null)
            {
                Puts($"Failed to give Combat Gear Box. Check your config for proper values.");
                return;
            }
            player.GiveItem(createitem);
            player.ChatMessage($"{CCLang("givegearbox", player.UserIDString)}");
        }

