        private void OpenCCUI(BasePlayer player, string command, string[] args)
        {
            if (player == null || !player.userID.Get().IsSteamId()) return;
            if (!config.mainSettings.enable) 
            {
                player.ChatMessage("Combat Classes is disabled.");
                return;
            }
            
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null)
            {
                InitializeCombatPlayers(player);
                combatPlayer = GetCombatPlayer(player);
                if (combatPlayer == null) 
                {
                    player.ChatMessage("Failed to initialize combat player data.");
                    return;
                }
            }

            // Open the main GUI panel instead of a specific class UI
            CCMain(player, "main");
        }
        private void GiveXPChat(BasePlayer player, string command, string[] args)
        {
            if (player == null || !player.userID.Get().IsSteamId() || !player.IsAdmin) return;
            var PlayerNameOrID = args[0];
            var Class = args[1];
            int Amount = Convert.ToInt32(args[2]);

            // Missing Name or ID
            if (string.IsNullOrEmpty(PlayerNameOrID))
            {
                player.ChatMessage(CCLang("CC_032", player.UserIDString, "PlayerNameOrID", config.mainSettings.givexp));
                return;
            }
            // Missing Class
            if (string.IsNullOrEmpty(Class))
            {
                player.ChatMessage(CCLang("CC_032", player.UserIDString, "Class", config.mainSettings.givexp));
                return;
            }
            // Missing Amount
            if (Amount <= 0)
            {
                player.ChatMessage(CCLang("CC_032", player.UserIDString, "Amount", config.mainSettings.givexp));
                return;
            }

            // All Classes
            if (Class == "all")
            {
                // SteamID
                if (ulong.TryParse(PlayerNameOrID, out ulong playerId) && playerId.IsSteamId())
                {
                    var PlayerToGive = FindPlayer(playerId);
                    if (_combatPlayers.combatPlayer.TryGetValue(PlayerToGive.userID, out var CombatPlayers))
                    {
                        foreach (var combatClass in CombatPlayers.combatclass)
                        {
                            GiveXPToClass(PlayerToGive, combatClass.Key, Amount);
                            player.ChatMessage(CCLang("CC_033", player.UserIDString, Amount, CCLang(combatClass.Key, player.UserIDString)));
                        }
                    }
                }
                else // DisplayName
                {
                    foreach (var AllPlayers in BasePlayer.allPlayerList.ToList())
                    {
                        if (AllPlayers.displayName.Contains(PlayerNameOrID))
                        {
                            if (_combatPlayers.combatPlayer.TryGetValue(AllPlayers.userID, out var CombatPlayers))
                            {
                                foreach (var combatClass in CombatPlayers.combatclass)
                                {
                                    GiveXPToClass(AllPlayers, combatClass.Key, Amount);
                                    AllPlayers.ChatMessage(CCLang("CC_033", AllPlayers.UserIDString, Amount, CCLang(combatClass.Key, AllPlayers.UserIDString)));
                                }
                            }
                        }
                    }
                }
            }
            // Class Specific
            else
            {
                // SteamID
                if (ulong.TryParse(PlayerNameOrID, out ulong playerId) && playerId.IsSteamId())
                {
                    var PlayerToGive = FindPlayer(playerId);
                    if (_combatPlayers.combatPlayer.TryGetValue(PlayerToGive.userID, out var CombatPlayers))
                    {
                        GiveXPToClass(PlayerToGive, Class, Amount);
                        player.ChatMessage(CCLang("CC_033", player.UserIDString, Amount, CCLang(Class, player.UserIDString)));
                    }
                }
                else // DisplayName
                {
                    foreach (var AllPlayers in BasePlayer.allPlayerList.ToList())
                    {
                        if (AllPlayers.displayName.Contains(PlayerNameOrID))
                        {
                            if (_combatPlayers.combatPlayer.TryGetValue(AllPlayers.userID, out var CombatPlayers))
                            {
                                GiveXPToClass(AllPlayers, Class, Amount);
                                player.ChatMessage(CCLang("CC_033", player.UserIDString, Amount, CCLang(Class, player.UserIDString)));
                            }
                        }
                    }
                }
            }
        }

        [ConsoleCommand("CCGiveXP")]
        private void GiveXPCommand(ConsoleSystem.Arg arg)
        {
            var player = arg.Player();
            // Allow console execution or require admin if called from in-game
            if (player != null && (!player.userID.Get().IsSteamId() || !player.IsAdmin)) return;

            var PlayerNameOrID = arg.GetString(0);
            var Class = arg.GetString(1);
            int Amount = Convert.ToInt32(arg.GetUInt(2));

            // Missing Name or ID
            if (string.IsNullOrEmpty(PlayerNameOrID))
            {
                Puts($"Missing PlayerNameOrID - chat command is /{config.mainSettings.givexp} <PlayerNameOrID> <Class> <Amount>");
                return;
            }
            // Missing Class
            if (string.IsNullOrEmpty(Class))
            {
                Puts($"Missing Class - chat command is /{config.mainSettings.givexp} <PlayerNameOrID> <Class> <Amount>");
                return;
            }
            // Missing Amount
            if (Amount <= 0)
            {
                Puts($"Missing Amount - chat command is /{config.mainSettings.givexp} <PlayerNameOrID> <Class> <Amount>");
                return;
            }

            // All Classes
            if (Class == "all")
            {
                // SteamID
                if (ulong.TryParse(PlayerNameOrID, out ulong playerId) && playerId.IsSteamId())
                {
                    var PlayerToGive = FindPlayer(playerId);
                    if (_CombatPlayerCache.TryGetValue(playerId, out var CombatPlayers))
                    {
                        foreach (var combatClass in CombatPlayers.combatclass)
                        {
                            if (PlayerToGive != null)
                            {
                                GiveXPToClass(PlayerToGive, combatClass.Key, Amount);
                                PlayerToGive.ChatMessage(CCLang("CC_033", PlayerToGive.UserIDString, Amount, CCLang(combatClass.Key, PlayerToGive.UserIDString)));
                                Puts($"{Amount} XP given to {PlayerToGive.displayName} in {combatClass.Key}");
                            }
                            else
                            {
                                GiveXPToClassByID(playerId, combatClass.Key, Amount);
                                Puts($"{Amount} XP given to player {playerId} in {combatClass.Key}");
                            }
                        }
                        SaveData();
                    }
                    else
                    {
                        Puts($"No combat class data found for player ID: {PlayerNameOrID}");
                    }
                }
                else // DisplayName
                {
                    foreach (var AllPlayers in BasePlayer.allPlayerList.ToList())
                    {
                        if (AllPlayers.displayName.ToLower().Contains(PlayerNameOrID))
                        {
                            if (_CombatPlayerCache.TryGetValue(AllPlayers.userID, out var CombatPlayers))
                            {
                                foreach (var combatClass in CombatPlayers.combatclass)
                                {
                                    GiveXPToClass(AllPlayers, combatClass.Key, Amount);
                                    AllPlayers.ChatMessage(CCLang("CC_033", AllPlayers.UserIDString, Amount, CCLang(combatClass.Key, AllPlayers.UserIDString)));
                                    Puts($"{Amount} XP given to {AllPlayers.displayName} in {combatClass.Key}");
                                }
                                SaveData();
                            }
                            else
                            {
                                Puts($"No combat class data found for player: {AllPlayers.displayName}");
                            }
                        }
                    }
                }
            }
            // Class Specific
            else
            {
                // SteamID
                if (ulong.TryParse(PlayerNameOrID, out ulong playerId) && playerId.IsSteamId())
                {
                    var PlayerToGive = FindPlayer(playerId);
                    if (_CombatPlayerCache.TryGetValue(playerId, out var CombatPlayers))
                    {
                        if (PlayerToGive != null)
                        {
                            GiveXPToClass(PlayerToGive, Class, Amount);
                            PlayerToGive.ChatMessage(CCLang("CC_033", PlayerToGive.UserIDString, Amount, CCLang(Class, PlayerToGive.UserIDString)));
                            Puts($"{Amount} XP given to {PlayerToGive.displayName} in {Class}");
                        }
                        else
                        {
                            GiveXPToClassByID(playerId, Class, Amount);
                            Puts($"{Amount} XP given to player {playerId} in {Class}");
                        }
                        SaveData();
                    }
                    else
                    {
                        Puts($"No combat class data found for player ID: {PlayerNameOrID}");
                    }
                }
                else // DisplayName
                {
                    foreach (var AllPlayers in BasePlayer.allPlayerList.ToList())
                    {
                        if (AllPlayers.displayName.ToLower().Contains(PlayerNameOrID))
                        {
                            if (_CombatPlayerCache.TryGetValue(AllPlayers.userID, out var CombatPlayers))
                            {
                                GiveXPToClass(AllPlayers, Class, Amount);
                                AllPlayers.ChatMessage(CCLang("CC_033", AllPlayers.UserIDString, Amount, CCLang(Class, AllPlayers.UserIDString)));
                                Puts($"{Amount} XP given to {AllPlayers.displayName} in {Class}");
                                SaveData();
                            }
                            else
                            {
                                Puts($"No combat class data found for player: {AllPlayers.displayName}");
                            }
                        }
                    }
                }
            }
        }

