        [ConsoleCommand("CC_MainUI")]
        private void Cmdccpanels(ConsoleSystem.Arg arg)
        {
            var player = arg.Player();
            if (player == null || !player.userID.Get().IsSteamId()) return;
            switch (arg.GetString(0))
            {
                case "main":
                    DestroyUIall(player);
                    CCMain(player);
                    return;
                case "player":
                    DestroyUIall(player);
                    CCMain(player, "main", Convert.ToUInt64(arg.GetUInt64(1)));
                    return;
                case "players":
                    DestroyUIall(player);
                    CCMain(player, "players", player.userID, arg.GetInt(2));
                    return;
                case "team":
                    DestroyUIall(player);
                    CCMain(player, "team", player.userID, arg.GetInt(2));
                    return;
                case "class":
                    DestroyUIall(player);
                    CCMain(player, "class", Convert.ToUInt64(arg.GetUInt64(2)));
                    switch (arg.GetString(1))
                    {
                        case "assault":
                            AssaultClassUI(player, "assault", Convert.ToUInt64(arg.GetUInt64(2)));
                            break;
                        case "medic":
                            MedicClassUI(player, "medic", Convert.ToUInt64(arg.GetUInt64(2)));
                            break;
                        case "heavy":
                            HeavyClassUI(player, "heavy", Convert.ToUInt64(arg.GetUInt64(2)));
                            break;
                        case "demolition":
                            DemolitionClassUI(player, "demolition", Convert.ToUInt64(arg.GetUInt64(2)));
                            break;
                        case "sniper":
                            SniperClassUI(player, "sniper", Convert.ToUInt64(arg.GetUInt64(2)));
                            break;
                        case "assassin":
                            AssassinClassUI(player, "assassin", Convert.ToUInt64(arg.GetUInt64(2)));
                            break;
                        case "scavenger":
                            ScavengerClassUI(player, "scavenger", Convert.ToUInt64(arg.GetUInt64(2)));
                            break;
                    }
                    return;
                case "close":
                    DestroyUIall(player);
                    CCHUD(player);
                    return;
                case "resize":
                    if (_ccthemeCache.ContainsKey(player.userID))
                    {
                        switch (arg.GetString(1))
                        {
                            case "up":
                                if (_ccthemeCache[player.userID].size >= 5) return;
                                _ccthemeCache[player.userID].size += 1;
                                break;
                            case "down":
                                if (_ccthemeCache[player.userID].size <= 0) return;
                                _ccthemeCache[player.userID].size -= 1;
                                break;
                        }
                    }
                    else
                    {
                        _ccthemeCache.Add(player.userID, new Themes
                        {
                            player = player.userID,
                            theme = arg.GetInt(1),
                            size = 0
                        });
                    }
                    SaveData();
                    DestroyUIall(player);
                    CCMain(player);
                    return;
                case "theme":
                    if (_ccthemeCache.ContainsKey(player.userID))
                    {
                        _ccthemeCache[player.userID].theme = arg.GetInt(1);
                    }
                    else
                    {
                        _ccthemeCache.Add(player.userID, new Themes
                        {
                            player = player.userID,
                            theme = arg.GetInt(1)
                        });
                    }
                    SaveData();
                    DestroyUIall(player);
                    CCMain(player);
                    CCHUD(player);
                    return;
                case "admin":
                    if(!player.IsAdmin) return;
                    DestroyUIall(player);
                    CCMain(player, "admin");
                    CCAdmin(player);
                    return;
                case "save":
                    SaveConfig();
                    break;
            }
        }

        [ConsoleCommand("CC_SwitchClass")]
        void CmdSwitchClass(ConsoleSystem.Arg arg)
        {
            var player = arg.Player();
            if (player == null) return;

            if (arg.Args == null || arg.Args.Length == 0) return;

            var selectedClass = arg.Args[0].ToString();

            // Logic to switch player's class
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            // Check Class Change Timer
            DateTime timelimit = combatPlayer.classchange.AddSeconds(config.mainSettings.classchangetimer);
            if(timelimit > DateTime.Now)
            {
                TimeSpan remaining = timelimit - DateTime.Now;
                player.ChatMessage(CCLang("CC_028", player.UserIDString, Math.Round(remaining.TotalSeconds)));
                return;
            }

            // Reset Class Timer
            combatPlayer.classtimer = DateTime.Now;

            // Validate selected class
            var availableClasses = new List<string> { "assault", "medic", "heavy", "sniper", "demolition", "assassin", "scavenger" };
            if (!availableClasses.Contains(selectedClass)) return;

            // Change player class and permissions
            combatPlayer.currentclass = selectedClass;
            combatPlayer.classchange = DateTime.Now;
            if (pingTimers.ContainsKey(player.userID) && pingTimers[player.userID] != null)
            {
                pingTimers[player.userID].Destroy();
                pingTimers[player.userID] = null;
            }
            if (_healingTimer != null)
            {
                _healingTimer.Destroy();
                _healingTimer = null;
            }
            CombatClassPermission(player);
            if(selectedClass == "assassin")
            {
                pingTimers[player.userID] = timer.Once(config.classSettings.AssassinClass["assassin"].pingtimer, () =>
                {
                    AssassinDetection(player);
                });
            }
            // Refresh UIs
            CCMain(player);
            CCHUD(player);
            if (config.gearBox.accessafterclasschange)
            {
                lastGearBoxTimes[player.userID] = null;
            }

            // Trigger class change event
            TriggerClassChange(player.userID, selectedClass);
        }

        [ConsoleCommand("CC_CalculatorUI")]
        void Cmdcalculator(ConsoleSystem.Arg arg)
        {
            var player = arg.Player();
            if (player == null || !player.userID.Get().IsSteamId()) return;

            if (player.IsAdmin)
            {
                if (!_CalculatorCache.TryGetValue(player.userID, out var calculators))
                {
                    _CalculatorCache.Add(player.userID, new Calculator
                    {
                        levelstart = config.mainSettings.levelstart,
                        increasedifficulty = config.mainSettings.increasedifficulty,
                        xpleveldifficultyincrease = config.mainSettings.xpleveldifficultyincrease,
                        maxlevel = config.mainSettings.maxlevel,
                        enableranks = config.mainSettings.enableranks,
                        increaserankdifficulty = config.mainSettings.increaserankdifficulty,
                        xprankdifficultyincrease = config.mainSettings.xprankdifficultyincrease,
                        maxrank = config.mainSettings.maxrank
                    });
                }

                string argCommand = arg.GetString(0);
                string argValue = arg.GetString(1);

                switch (argCommand)
                {
                    case "levelstart":
                        if (int.TryParse(argValue, out int levelstart))
                        {
                            _CalculatorCache[player.userID].levelstart = levelstart;
                        }
                        break;
                    case "increasedifficulty":
                        if (bool.TryParse(argValue, out bool increasedifficulty))
                        {
                            _CalculatorCache[player.userID].increasedifficulty = increasedifficulty;
                        }
                        break;
                    case "xpleveldifficultyincrease":
                        if (double.TryParse(argValue, out double xpleveldifficultyincrease))
                        {
                            _CalculatorCache[player.userID].xpleveldifficultyincrease = xpleveldifficultyincrease;
                        }
                        break;
                    case "maxlevel":
                        if (int.TryParse(argValue, out int maxlevel))
                        {
                            _CalculatorCache[player.userID].maxlevel = maxlevel;
                        }
                        break;
                    case "enableranks":
                        if (bool.TryParse(argValue, out bool enableranks))
                        {
                            _CalculatorCache[player.userID].enableranks = enableranks;
                        }
                        break;
                    case "increaserankdifficulty":
                        if (bool.TryParse(argValue, out bool increaserankdifficulty))
                        {
                            _CalculatorCache[player.userID].increaserankdifficulty = increaserankdifficulty;
                        }
                        break;
                    case "xprankdifficultyincrease":
                        if (double.TryParse(argValue, out double xprankdifficultyincrease))
                        {
                            _CalculatorCache[player.userID].xprankdifficultyincrease = xprankdifficultyincrease;
                        }
                        break;
                    case "maxrank":
                        if (int.TryParse(argValue, out int maxrank))
                        {
                            _CalculatorCache[player.userID].maxrank = maxrank;
                        }
                        break;
                }
            }

            if (arg.GetString(0) == "open")
            {
                DestroyUi(player, CC_Calculator);
                CombatCalculator(player);
            }
            else if (arg.GetString(0) == "close")
            {
                DestroyUi(player, CC_Calculator);
            }
            else
            {
                DestroyUi(player, CC_Calculator);
                CombatCalculator(player, arg.GetInt(0));
            }
        }

