        private void GlobalKillNotice(string attacker, string victim)
        {
            if (attacker == string.Empty || victim == string.Empty) return;
            foreach (var player in BasePlayer.activePlayerList)
            {
                if (player == null) continue;
                player.ChatMessage(CCLang("CC_035", player.UserIDString, attacker, victim));
            }
        }
        private void GlobalLevelNotice(string playername, int level, string combatclass)
        {
            if (playername == string.Empty || level < 1 || combatclass == string.Empty) return;
            foreach (var player in BasePlayer.activePlayerList)
            {
                if (player == null) continue;
                player.ChatMessage(CCLang("CC_034", player.UserIDString, player.displayName, level, combatclass));
            }
        }
