        #region UI
        private void CCHUD(BasePlayer player, bool moving = false)
        {
            if (player == null || !player.userID.Get().IsSteamId() || !player.isSpawned || !player.IsConnected) return;
            CombatPlayer combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return;

            // Ensure the dictionary is properly initialized and contains the current class
            if (!combatPlayer.combatclass.TryGetValue(combatPlayer.currentclass, out var combatClass) || combatClass == null)
            {
                timer.Once(5f, () => CCHUD(player));
                return;
            }

            // Destroy current HUD before update
            DestroyUi(player, CC_HUD);

            #region Layout
            var UIelements = new CuiElementContainer();
            int HUD_left = -150;
            int HUD_bottom = 80;
            int HUD_right = HUD_left + 300;
            int HUD_top = HUD_bottom + 20;
            float height = 1f;
            int row = 1;
            int font = 10;
            #endregion

            // HUD Panel
            var hudPanel = new CuiElement
            {
                Name = CC_HUD,
                Parent = moving ? "Overlay" : "Hud",
                DestroyUi = CC_HUD,
                Components =
                {
                    new CuiImageComponent { Color = ThemeColor(player, "cui", .2) },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = ".5 0",
                        AnchorMax = ".5 0",
                        OffsetMin = $"{HUD_left + combatPlayer.cc_hud_offset.x} {HUD_bottom + combatPlayer.cc_hud_offset.y}",
                        OffsetMax = $"{HUD_right + combatPlayer.cc_hud_offset.x} {HUD_top + combatPlayer.cc_hud_offset.y}"
                    }
                }
            };
            if (moving)
            {
                hudPanel.Components.Add(new CuiDraggableComponent
                {
                    LimitToParent = false,
                    MaxDistance = -1f,
                    AllowSwapping = false,
                    DropAnywhere = true,
                    DragAlpha = 1f,
                    ParentLimitIndex = 1,
                    ParentPadding = "0 0",
                    KeepOnTop = false,
                    PositionRPC = CommunityEntity.DraggablePositionSendType.Relative,
                    MoveToAnchor = true,
                    RebuildAnchor = true
                });
                hudPanel.Components.Add(new CuiNeedsCursorComponent());
            }
            UIelements.Add(hudPanel);

            // HUD Data
            double levelpercent = GetLevelPercent(combatPlayer, combatPlayer.currentclass);
            UIelements.Add(UILabel($"{CCLang(combatPlayer.currentclass, player.UserIDString)}", row, height, TextAnchor.MiddleLeft, font, ".01", ".25", "1 1 1 1"), CC_HUD);
            UIelements.Add(UILabel($"{CCLang("CC_002", player.UserIDString)}:", row, height, TextAnchor.MiddleLeft, font, ".25", ".35", "1 1 1 1"), CC_HUD);
            UIelements.Add(UILabel($"{combatClass.level}", row, height, TextAnchor.MiddleLeft, font, ".35", ".45", "1 1 1 1"), CC_HUD);
            double range = 0.64;
            double xpbar = 0.35 + ((levelpercent / 100) * range);
            if (levelpercent < 1)
            {
                xpbar = .98;
            }
            UIelements.Add(UIInputbackground(row, height - .15f, "0 0 0 1", ".45", ".98", .15), CC_HUD);
            UIelements.Add(UIInputbackground(row, height - .15f, ThemeColor(player, "cui"), ".45", $"{xpbar}", .15), CC_HUD);
            UIelements.Add(UILabel($"{combatClass.xp} / {GetLevelRequirement(combatPlayer, combatPlayer.currentclass)} ({levelpercent}%)", row, height, TextAnchor.MiddleCenter, 9, ".45", ".98", "1 1 1 1"), CC_HUD);

            if (moving)
            {
                UIelements.Add(new CuiButton
                {
                    Button = { Color = "1 1 1 0", Command = "ccstopmovinghud" },
                    Text = { Text = "X", FontSize = 10, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" },
                    RectTransform = { AnchorMin = "1 1", AnchorMax = "1 1", OffsetMin = "-16 0", OffsetMax = "0 16" }
                }, CC_HUD, "CC_HUD_Move_Stop");
            }

            CuiHelper.AddUi(player, UIelements);
        }
