                    // - rowGap: vertical space between class rows within the scroll area
                    // - topMargin/bottomMargin: vertical bounds inside the scroll area (0..1)
                    // - rowHeight: computed height allocated per class row so the full list fits
                    // - rowStep: rowHeight + rowGap; distance to move down for each next row
                    // Adjust rowGap or the margins to fine-tune packing without touching individual item contents.
                    int classCount = Math.Max(1, combatPlayer.combatclass.Count);
                    double rowGap = .01;         // adjustable spacing between rows
                    double topMargin = .99;       // top bound inside scroll view
                    double bottomMargin = .01;    // bottom bound inside scroll view
                    double availableHeight = topMargin - bottomMargin;
                    double rowHeight = Math.Round((availableHeight - ((classCount - 1) * rowGap)) / classCount, 4);
                    double rowStep = Math.Round(rowHeight + rowGap, 4);
                    double classtop = topMargin;
                    foreach (var combatclass in combatPlayer.combatclass)
                    {
                        string classPanelName = "Class_" + combatclass.Key;
                        int classnum = 1;
                        double levelpercent = GetLevelPercent(combatPlayer, combatclass.Key);

                        // Add class panel
                        string selected = "0 0 0 0";
                        if (combatclass.Key == combatPlayer.currentclass)
                        {
                            selected = ThemeColor(player, "cui");
                        }
                        // Outer and inner panels for each class row, positioned using the dynamic rowHeight/rowStep values above.
                        UIelements.Add(UIPanel($".01 {classtop - rowHeight}", $".99 {classtop}", selected), CC_ScrollView, classPanelName + "1");
                        UIelements.Add(UIPanel($".015 {classtop - rowHeight + .005}", $".985 {classtop - .005}", ".1 .1 .1 1"), CC_ScrollView, classPanelName);

                        // Add class image
                        UIelements.Add(new CuiElement
                        {
                            Parent = classPanelName,
                            Components =
                            {
                                new CuiRawImageComponent
                                {
                                    Png = GetImage("CC" + combatclass.Key).ToString(),
                                },
                                new CuiRectTransformComponent
                                {
                                    AnchorMin = $".01 .05",
                                    AnchorMax = $".20 .95"
                                }
                            }
                        });

                        // Add class stats labels
                        UIelements.Add(UILabel($"{CCLang("CC_002", player.UserIDString)}:", classnum, classheight, TextAnchor.MiddleLeft, font, ".21", ".325", "1 1 1 1"), classPanelName);
                        UIelements.Add(UILabel($"{combatclass.Value.level}", classnum, classheight, TextAnchor.MiddleLeft, font, ".325", ".4", "1 1 1 1"), classPanelName);
                        double range = 0.175;
                        double xpbar = 0.4 + ((levelpercent / 100) * range);
                        if (levelpercent < 1)
                        {
                            xpbar = .39;
                        }
                        UIelements.Add(UIInputbackground(classnum, classheight - .05f, "0 0 0 1", ".4", ".575", .06), classPanelName);
                        UIelements.Add(UIInputbackground(classnum, classheight - .05f, ThemeColor(player, "cui"), ".4", $"{xpbar}", .06), classPanelName);
                        UIelements.Add(UILabel($"({levelpercent}%)", classnum, classheight, TextAnchor.MiddleCenter, 9, ".4", ".575", "1 1 1 1"), classPanelName);

                        UIelements.Add(UILabel($"{CCLang("CC_008", player.UserIDString)}:", classnum, classheight, TextAnchor.MiddleLeft, font, ".65", ".8", "1 1 1 1"), classPanelName);
                        UIelements.Add(UILabel($"{combatclass.Value.playerkills}", classnum, classheight, TextAnchor.MiddleLeft, font, ".8", ".99", "1 1 1 1"), classPanelName);
                        classnum++;

                        UIelements.Add(UILabel($"{CCLang("CC_003", player.UserIDString)}:", classnum, classheight, TextAnchor.MiddleLeft, font, ".21", ".325", "1 1 1 1"), classPanelName);
                        UIelements.Add(UILabel($"{combatclass.Value.xp} / {GetLevelRequirement(combatPlayer, combatclass.Key)}", classnum, classheight, TextAnchor.MiddleLeft, font, ".325", ".5", "1 1 1 1"), classPanelName);
                        UIelements.Add(UILabel($"{CCLang("CC_007", player.UserIDString)}:", classnum, classheight, TextAnchor.MiddleLeft, font, ".65", ".8", "1 1 1 1"), classPanelName);
                        UIelements.Add(UILabel($"{combatclass.Value.npckills}", classnum, classheight, TextAnchor.MiddleLeft, font, ".8", ".99", "1 1 1 1"), classPanelName);
                        classnum++;

                        UIelements.Add(UILabel($"{CCLang("CC_005", player.UserIDString)}:", classnum, classheight, TextAnchor.MiddleLeft, font, ".21", ".325", "1 1 1 1"), classPanelName);
                        UIelements.Add(UILabel($"{combatclass.Value.xptotal}", classnum, classheight, TextAnchor.MiddleLeft, font, ".325", ".4", "1 1 1 1"), classPanelName);
                        UIelements.Add(UILabel($"{CCLang("CC_009", player.UserIDString)}:", classnum, classheight, TextAnchor.MiddleLeft, font, ".65", ".8", "1 1 1 1"), classPanelName);
                        UIelements.Add(UILabel($"{combatclass.Value.deaths}", classnum, classheight, TextAnchor.MiddleLeft, font, ".8", ".99", "1 1 1 1"), classPanelName);
                        classnum++;

                        if (config.mainSettings.enableranks)
                        {
                            UIelements.Add(UILabel($"{CCLang("CC_004", player.UserIDString)}:", classnum, classheight, TextAnchor.MiddleLeft, font, ".21", ".325", "1 1 1 1"), classPanelName);
                            UIelements.Add(UILabel($"{combatclass.Value.rank}", classnum, classheight, TextAnchor.MiddleLeft, font, ".325", ".4", "1 1 1 1"), classPanelName);
                        }
                        UIelements.Add(UILabel($"{CCLang("CC_010", player.UserIDString)}:", classnum, classheight, TextAnchor.MiddleLeft, font, ".65", ".8", "1 1 1 1"), classPanelName);
                        UIelements.Add(UILabel($"{combatclass.Value.suicides}", classnum, classheight, TextAnchor.MiddleLeft, font, ".8", ".99", "1 1 1 1"), classPanelName);


                        // View Class
                        string viewAnchorMin = ".87 .56";
                        string viewAnchorMax = "1 .82";
                        UIelements.Add(new CuiElement
                        {
                            Parent = classPanelName,
                            Components =
                            {
                                new CuiRawImageComponent
                                {
                                    Png = GetImage(CCgreen2).ToString(),
                                },
                                new CuiRectTransformComponent
                                {
                                    AnchorMin = viewAnchorMin,
                                    AnchorMax = viewAnchorMax
                                }
                            }
                        });
                        UIelements.Add(new CuiButton
                        {
                            Button =
                            {
                            Command = $"CC_MainUI class {combatclass.Key} {cplayerId.ToString()}",
                            Color = "0 0 0 0"
                            },
                            RectTransform =
                            {
                                    AnchorMin = viewAnchorMin,
                                    AnchorMax = viewAnchorMax
                            },
                            Text =
                            {
                                Text = CCLang("CC_022", player.UserIDString),
                                FontSize = 8,
                                Align = TextAnchor.MiddleCenter
                            }
                        }, classPanelName);
                        // Change Class
                        if (cplayerId == player.userID)
                        {    
                            string classAnchorMin = ".87 .16";
                            string classAnchorMax = "1 .42";
                            string classbutton = CCgreen2;
                            string currenclass = CCLang("CC_023", player.UserIDString);
                            if (combatPlayer.currentclass == combatclass.Key)
                            {
                                classbutton = CCred;
                                currenclass = CCLang("CC_006", player.UserIDString);
                            }
                            UIelements.Add(new CuiElement
                            {
                                Parent = classPanelName,
                                Components =
                                {
                                    new CuiRawImageComponent
                                    {
                                        Png = GetImage(classbutton).ToString(),
                                    },
                                    new CuiRectTransformComponent
                                    {
                                        AnchorMin = classAnchorMin,
                                        AnchorMax = classAnchorMax
                                    }
                                }
                            });
                            UIelements.Add(new CuiButton
                            {
                                Button =
                                {
                                Command = $"CC_SwitchClass {combatclass.Key}",
                                Color = "0 0 0 0"
                                },
                                RectTransform =
                                {
                                        AnchorMin = classAnchorMin,
                                        AnchorMax = classAnchorMax
                                },
                                Text =
                                {
                                    Text = currenclass,
                                    FontSize = 8,
                                    Align = TextAnchor.MiddleCenter
                                }
                            }, classPanelName);
                        }
                        
                        // Move down by one row.
                        classtop -= rowStep;
                    }
                    break;
                case "players":
                    // Labels
                    UIelements.Add(UIPanel(".20 .01", ".98 .63", "0 0 0 0"), CC_Main, CC_B);
                    UIelements.Add(UILabel($"{CCLang("CC_025", player.UserIDString)}", 1, playerheight, TextAnchor.MiddleLeft, font, ".02", ".3", "1 1 1 1"), CC_B);
                    UIelements.Add(UILabel($"[{CCLang("CC_002", player.UserIDString)}] {CCLang("CC_006", player.UserIDString)}", 1, playerheight, TextAnchor.MiddleLeft, font, ".3", ".5", "1 1 1 1"), CC_B);
                    UIelements.Add(UILabel($"{CCLang("CC_026", player.UserIDString)}", 1, playerheight, TextAnchor.MiddleRight, font, ".5", ".65", "1 1 1 1"), CC_B);
                    UIelements.Add(UILabel($"{CCLang("CC_027", player.UserIDString)}", 1, playerheight, TextAnchor.MiddleCenter, font, ".7", ".99", "1 1 1 1"), CC_B);
                    
                    var orderedPlayers = _combatPlayers.combatPlayer.OrderBy(p => p.Value.started).ToList();

                    int playercount = orderedPlayers.Count();
                    int itemsPerPage = 25;
                    if(playercount < 25)
                    {
                        itemsPerPage = playercount;
                    }
                    int startIndex = pagenum * itemsPerPage;
                    int endIndex = Math.Min(startIndex + itemsPerPage, playercount);
                    int actualIndex = 0;
                    playerheight = 1f / (itemsPerPage);

                    // Player List
                    UIelements.Add(UIPanel(".20 .01", ".98 .575", "0 0 0 0"), CC_Main, CC_ScrollPage);
                    UIelements.Add(UIScroll(CC_ScrollPage, "0 .1", "1.01 1", ThemeColor(player, "cui"), itemsPerPage));

                    for (int i = startIndex; i < endIndex; i++)
                    {
                        var iplayer = orderedPlayers[i];
                        var playername = FindPlayer(iplayer.Key);

                        var playerclass = iplayer.Value.combatclass[iplayer.Value.currentclass];
                        CombatPlayer playercombat = GetCombatPlayer(playername);
                        double levelpercent = GetLevelPercent(playercombat, iplayer.Value.currentclass);
                        double range = 0.26;
