                        UIelements.Add(UILabel($"{playerclass.xp} / {reqxp} ({levelpercent}%)", actualIndex, playerheight, TextAnchor.MiddleCenter, 9, ".7", ".96", "1 1 1 1"), CC_ScrollView);

