                    UIelements.Add(UILabel($"[{CCLang("CC_002", player.UserIDString)}] {CCLang("CC_006", player.UserIDString)}", 1, playerheight, TextAnchor.MiddleLeft, font, ".3", ".5", "1 1 1 1"), CC_B);
                    UIelements.Add(UILabel($"{CCLang("CC_026", player.UserIDString)}", 1, playerheight, TextAnchor.MiddleRight, font, ".5", ".65", "1 1 1 1"), CC_B);
                    UIelements.Add(UILabel($"{CCLang("CC_027", player.UserIDString)}", 1, playerheight, TextAnchor.MiddleCenter, font, ".7", ".99", "1 1 1 1"), CC_B);

                    itemsPerPage = 10;
