                        actualIndex++;
                    }

                    // Pages
                    UIelements.Add(UIPanel("0 0", "1 .1", "0 0 0 0"), CC_ScrollPage, "CC_CalCulatorPages");
                    back = pagenum <= 0 ? 0 : pagenum - 1;
                    next = (pagenum + 1) * itemsPerPage < 10 ? pagenum + 1 : pagenum;

                    // Previous Page Button
                    if (pagenum > 0)
                    {
                        UIelements.Add(UIInputbackground(1, .8f, "0 0 0 1", ".09", ".41", .24), "CC_CalCulatorPages");
                        UIelements.Add(UIMenuButton($"CC_MainUI players {player.userID} {back}", 1, .75f, 10, ThemeColor(player, "cui"), CCLang("pageprev", player.UserIDString), ".1", ".4", TextAnchor.MiddleCenter, "1 1 1 1", .25), "CC_CalCulatorPages");
                    }

                    // Next Page Button
                    if ((pagenum + 1) * itemsPerPage < 10)
                    {
                        UIelements.Add(UIInputbackground(1, .8f, "0 0 0 1", ".59", ".91", .24), "CC_CalCulatorPages");
                        UIelements.Add(UIMenuButton($"CC_MainUI players {player.userID} {next}", 1, .75f, 10, ThemeColor(player, "cui"), CCLang("pagenext", player.UserIDString), ".6", ".9", TextAnchor.MiddleCenter, "1 1 1 1", .25), "CC_CalCulatorPages");
                    }

                    break;
                case "class":
                    UIelements.Add(UIPanel(".20 .01", ".98 .63", "0 0 0 0"), CC_Main, CC_B);
                    break;
            }

            #region Menu           
            UIelements.Add(UIPanel(".0075 .15", ".20 .65", "1 1 1 0"), CC_Main, CC_Menu);
            
            // Menu  Background
            UIelements.Add(new CuiElement
            {
                Parent = CC_Menu,
                Components =
                {
                    new CuiRawImageComponent
                    {
                        Png = GetImage(CCmbg+_ccthemeCache[player.userID].theme).ToString()
                    },
