            UIelements.Add(UILabel($"{CCLang("CC_menu_001", player.UserIDString)}", 1, .11f, TextAnchor.LowerLeft, 13, ".06", ".94", "1 1 0 1"), CC_Menu);
            
            // UI Size Buttons
            UIelements.Add(UIPanel(".875 .875", ".96 .96", "1 1 1 0"), CC_Menu, "ThemeSize");  
            if (_ccthemeCache[player.userID].size < 5)
            {
                UIelements.Add(UIImage("ThemeSize", CCresizeup, 1, .5f, "0", "1", 0, .02, .01));
                UIelements.Add(UIButton($"CC_MainUI resize up", 1, .5f, 0, "0 0 0 0", "", "0", "1", TextAnchor.MiddleCenter, "1 1 0 1"), "ThemeSize");
            }
            if (_ccthemeCache[player.userID].size > 0)
            {
                UIelements.Add(UIImage("ThemeSize", CCresizedown, 2, .5f, "0", "1", 0, .02, .01));
                UIelements.Add(UIButton($"CC_MainUI resize down", 2, .5f, 0, "0 0 0 0", "", "0", "1", TextAnchor.MiddleCenter, "1 1 0 1"), "ThemeSize");
