            UIelements.Add(UIPanel(".025 .0275", ".975 .85", "1 1 1 0"), CC_Menu, "MenuButtons");
            UIelements.Add(UIMenuButton("CC_MainUI main", menupos++, menubutton, font, "0 0 0 0", $" <color={ThemeColor(player, "hex")}>☢</color>  {CCLang("CC_menu_002", player.UserIDString)}", ".02", ".94", TextAnchor.LowerLeft, "1 1 1 1", top), "MenuButtons");
            if (player.Team != null && config.mainSettings.useteams)
            {
                UIelements.Add(UIMenuButton("CC_MainUI team", menupos++, menubutton, font, "0 0 0 0", $" <color={ThemeColor(player, "hex")}>☢</color>  {CCLang("CC_menu_007", player.UserIDString)}", ".02", ".94", TextAnchor.LowerLeft, "1 1 1 1", top), "MenuButtons");
            }
            UIelements.Add(UIMenuButton("CC_MainUI players", menupos++, menubutton, font, "0 0 0 0", $" <color={ThemeColor(player, "hex")}>☢</color>  {CCLang("CC_menu_005", player.UserIDString)}", ".02", ".94", TextAnchor.LowerLeft, "1 1 1 1", top), "MenuButtons");
