            UIelements.Add(UIMenuButton("CC_CalculatorUI open", menupos++, menubutton, font, "0 0 0 0", $" <color={ThemeColor(player, "hex")}>☢</color>  {CCLang("CC_menu_006", player.UserIDString)}", ".02", ".94", TextAnchor.LowerLeft, "1 1 1 1", top), "MenuButtons");
            UIelements.Add(UIMenuButton("CC_MainUI close", menupos++, menubutton, font, "0 0 0 0", $" <color={ThemeColor(player, "hex")}>☢</color>  {CCLang("CC_close", player.UserIDString)}", ".02", ".94", TextAnchor.LowerLeft, "1 1 1 1", top), "MenuButtons");
