                UIelements.Add(UIMenuButton("CC_MainUI admin", menupos++, menubutton, font, "0 0 0 0", $" <color={ThemeColor(player, "hex")}>☢</color>  {CCLang("CC_admin_001", player.UserIDString)}", ".02", ".94", TextAnchor.LowerLeft, "1 1 1 1", top), "MenuButtons");
                if (CombatClassesNPCAddon != null)
                {
                    UIelements.Add(UIMenuButton("CCnpc_AdminData openui", menupos++, menubutton, font, "0 0 0 0", $" <color={ThemeColor(player, "hex")}>☢</color>  {CCLang("CC_admin_S061", player.UserIDString)}", ".02", ".94", TextAnchor.LowerLeft, "1 1 1 1", top), "MenuButtons");
                }
                UIelements.Add(UIMenuButton("CC_MainUI save", menupos++, menubutton, font, "0 0 0 0", $" <color={ThemeColor(player, "hex")}>☢</color>  {CCLang("CC_admin_S041", player.UserIDString)}", ".02", ".94", TextAnchor.LowerLeft, "1 1 1 1", top), "MenuButtons");
