                    new CuiRawImageComponent
                    {
                        Png = GetImage(CCTheme+_ccthemeCache[player.userID].theme).ToString()
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 0",
                        AnchorMax = "1 1"
                    }
                }
            });
            UIelements.Add(UIMenuButton("CC_MainUI theme 1", 1, 1, 0, "0 0 0 0", "", ".06", ".19", TextAnchor.LowerLeft, "1 1 1 1", top), "ThemeSelection");
            UIelements.Add(UIMenuButton("CC_MainUI theme 2", 1, 1, 0, "0 0 0 0", "", ".26", ".38", TextAnchor.LowerLeft, "1 1 1 1", top), "ThemeSelection");
            UIelements.Add(UIMenuButton("CC_MainUI theme 3", 1, 1, 0, "0 0 0 0", "", ".45", ".58", TextAnchor.LowerLeft, "1 1 1 1", top), "ThemeSelection");
            UIelements.Add(UIMenuButton("CC_MainUI theme 4", 1, 1, 0, "0 0 0 0", "", ".63", ".76", TextAnchor.LowerLeft, "1 1 1 1", top), "ThemeSelection");
            UIelements.Add(UIMenuButton("CC_MainUI theme 5", 1, 1, 0, "0 0 0 0", "", ".80", ".93", TextAnchor.LowerLeft, "1 1 1 1", top), "ThemeSelection");
            #endregion
            
            #endregion

            CuiHelper.AddUi(player, UIelements);
        }
        private void MedicClassUI(BasePlayer player, string viewclass = "medic", ulong cplayerId = 0)
        {
            if (player == null || !player.userID.Get().IsSteamId()) return;
            var cplayer = player;
            if (cplayerId != 0 && cplayerId.IsSteamId())
            {
                cplayer = FindPlayer(cplayerId);
            }
            CombatPlayer combatPlayer = GetCombatPlayer(cplayer);
            if (combatPlayer == null) return;
            var classdata = config.classSettings.MedicClass[viewclass];

            #region Layout
