        private void CombatCalculator(BasePlayer player, int page = 0)
        {
            if (player == null || !player.userID.Get().IsSteamId()) return;

            #region Layout
            var UIelements = new CuiElementContainer();
            float height = 0.045f;
            double width = .015;
            int font = 11;
            int options = 2;
            int size = _ccthemeCache[player.userID].size;
            int Mleft = 175 + (size * 10);
            int Mright = 450 + (size * 10);
            int Mtop = 290 + (size * 10) - config.mainSettings.uiVerticalOffset;
            int Mbottom = -210 - (size * 10) - config.mainSettings.uiVerticalOffset;
            double top = .01;
            double bottom = .01;
            string shade = ".3 .3 .3 .3";
            #endregion

            // Set Values from config
            #region Default Values
            int levelstart = config.mainSettings.levelstart;
            bool leveldiffculty = config.mainSettings.increasedifficulty;
            double leveldifficultyamount = config.mainSettings.xpleveldifficultyincrease;
            int maxlevel = config.mainSettings.maxlevel;
            bool ranks = config.mainSettings.enableranks;
            bool rankdifficulty = config.mainSettings.increaserankdifficulty;
            double rankdifficultyamount = config.mainSettings.xprankdifficultyincrease;
            int maxrank = config.mainSettings.maxrank;
            int level = 0;
            int totalxp = 0;
            int rank = 0;
            double requiredlevelxp = 0;
            #endregion

            #region Calulator UI Panel
            // Calculator Ui
            UIelements.Add(new CuiPanel
            {
                Image =
                {
                    Color = ".1 .1 .1 .99",
                },
                RectTransform =
                {
                    AnchorMin = "0.6 0.5",
                    AnchorMax = "0.6 0.5",
                    OffsetMin = $"{Mleft} {Mbottom}",
                    OffsetMax = $"{Mright} {Mtop}",
                },
                CursorEnabled = true
            }, "Overlay", CC_Calculator);
            UIelements.Add(new CuiElement
            {
                Parent = CC_Calculator,
                Components =
                {
                    new CuiRawImageComponent
                    {
                        Png = GetImage(CCbg+_ccthemeCache[player.userID].theme).ToString(),
                        FadeIn = 1
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 0",
                        AnchorMax = "1 1"
                    }
                }
            });
            
            // Top Right Close
            UIelements.Add(new CuiElement
            {
                Parent = CC_Calculator,
                Components =
                {
                    new CuiRawImageComponent
                    {
                        Png = GetImage(CCclose).ToString()
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = ".96 .96",
                        AnchorMax = ".99 .99"
                    }
                }
            });
            UIelements.Add(new CuiButton
            {
                Button =
                {
                    Command = "CC_CalculatorUI close",
                    Color = "0 0 0 0"
                },
                RectTransform =
                {
                        AnchorMin = ".95 .95",
                        AnchorMax = "1 1"
                }
            }, CC_Calculator);
            
            // Title
            UIelements.Add(UILabel($"<b>══ ⋆★ {CCLang("CC_031", player.UserIDString)} ★⋆ ══</b>", 1, height, TextAnchor.MiddleCenter, 13, ".05", ".95", "1 1 1 1"), CC_Calculator);

            // Adjustable Calculator Options (Admins Only)
            if(player.IsAdmin)
            {
                if(!_CalculatorCache.TryGetValue(player.userID, out var calculators))
                {
                    _CalculatorCache.Add(player.userID, new Calculator
                    {
                        levelstart = config.mainSettings.levelstart,
                        increasedifficulty = config.mainSettings.increasedifficulty,
                        maxlevel = config.mainSettings.maxlevel,
                        enableranks = config.mainSettings.enableranks,
                        increaserankdifficulty = config.mainSettings.increaserankdifficulty,
                        maxrank = config.mainSettings.maxrank
                    });
                }
                var cplayer = _CalculatorCache[player.userID];
                if (cplayer != null)
                {
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S002", player.UserIDString)}", options, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Calculator);
                    UIelements.Add(UIInputbackground(options, height, "0 0 .1 .75", ".5", ".98", top, bottom), CC_Calculator);
                    UIelements.Add(UIInput(CC_Calculator, $"CC_CalculatorUI levelstart {UserInputText}", options, height, 12, $"{cplayer.levelstart}", ".5", ".98", TextAnchor.MiddleLeft, "1 1 1 1"));
                    options++;
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S003", player.UserIDString)}:", options, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Calculator);
                    UIelements.Add(Toggle($"CC_CalculatorUI increasedifficulty", options, height, cplayer.increasedifficulty, ".5", width), CC_Calculator);
                    if (cplayer.increasedifficulty)
                    {
                        options++;
                        UIelements.Add(UILabel($"{CCLang("CC_admin_S004", player.UserIDString)}", options, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Calculator);
                        UIelements.Add(UIInputbackground(options, height, "0 0 .1 .75", ".5", ".75", top, bottom), CC_Calculator);
                        UIelements.Add(UIInput(CC_Calculator, $"CC_CalculatorUI xpleveldifficultyincrease {UserInputText}", options, height, 12, $"{cplayer.xpleveldifficultyincrease}", ".5", ".75", TextAnchor.MiddleLeft, "1 1 1 1"));
                        UIelements.Add(UILabel($"{cplayer.xpleveldifficultyincrease * 100}%", options, height, TextAnchor.MiddleLeft, font, ".76", ".98", "1 1 1 1"), CC_Calculator);
                    }
                    options++;
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S005", player.UserIDString)}", options, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Calculator);
                    UIelements.Add(UIInputbackground(options, height, "0 0 .1 .75", ".5", ".98", top, bottom), CC_Calculator);
                    UIelements.Add(UIInput(CC_Calculator, $"CC_CalculatorUI maxlevel {UserInputText}", options, height, 12, $"{cplayer.maxlevel}", ".5", ".98", TextAnchor.MiddleLeft, "1 1 1 1"));
                    
                    // Ranks N/A
                    /*
                    options++;
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S009", player.UserIDString)}:", options, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Calculator);
                    UIelements.Add(Toggle($"CC_CalculatorUI increaserankdifficulty", options, height, cplayer.increaserankdifficulty, ".5", width), CC_Calculator);
                    if (config.mainSettings.increaserankdifficulty)
                    {
                        options++;
                        UIelements.Add(UILabel($"{CCLang("CC_admin_S010", player.UserIDString)}", options, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Calculator);
                        UIelements.Add(UIInputbackground(options, height, "0 0 .1 .75", ".5", ".75", top, bottom), CC_Admin);
                        UIelements.Add(UIInput(CC_Calculator, $"CC_CalculatorUI xprankdifficultyincrease {UserInputText}", options, height, 12, $"{cplayer.xprankdifficultyincrease}", ".5", ".75", TextAnchor.MiddleLeft, "1 1 1 1"));
                        UIelements.Add(UILabel($"{cplayer.xprankdifficultyincrease * 100}%", options, height, TextAnchor.MiddleLeft, font, ".76", ".98", "1 1 1 1"), CC_Calculator);
                    }
                    options++;
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S007", player.UserIDString)}", options, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Calculator);
                    UIelements.Add(UIInputbackground(options, height, "0 0 .1 .75", ".5", ".98", top, bottom), CC_Calculator);
                    UIelements.Add(UIInput(CC_Calculator, $"CC_CalculatorUI maxrank {UserInputText}", options, height, 12, $"{cplayer.maxrank}", ".5", ".98", TextAnchor.MiddleLeft, "1 1 1 1"));
                    */

                    // Overwrite values with adjustable values
                    levelstart = cplayer.levelstart;
                    leveldiffculty = cplayer.increasedifficulty;
                    leveldifficultyamount = cplayer.xpleveldifficultyincrease;
                    maxlevel = cplayer.maxlevel;
                    ranks = cplayer.enableranks;
                    //rankdifficulty = cplayer.increaserankdifficulty;
                    rankdifficulty = false;
                    rankdifficultyamount = cplayer.xprankdifficultyincrease;
                    maxrank = cplayer.maxrank;
                }
            }

            int itemsPerPage = 100;
            int startIndex = page * itemsPerPage;
            int endIndex = Math.Min(startIndex + itemsPerPage, maxlevel);

            // Level List Headers
            options++;
            UIelements.Add(UILabel($"{CCLang("CC_002", player.UserIDString)}", options, height, TextAnchor.MiddleLeft, 12, ".01", ".34", "1 1 1 1"), CC_Calculator);
            UIelements.Add(UILabel($"{CCLang("CC_003", player.UserIDString)}", options, height, TextAnchor.MiddleLeft, 12, ".35", ".68", "1 1 1 1"), CC_Calculator);
            UIelements.Add(UILabel($"{CCLang("CC_005", player.UserIDString)}", options, height, TextAnchor.MiddleLeft, 12, ".69", ".99", "1 1 1 1"), CC_Calculator);

            // Scroll Box
            float levelboxtop = 1 - (height * options);
            UIelements.Add(UIPanel(".01 .01", $".98 {levelboxtop}", "0 0 0 0"), CC_Calculator, CC_ScrollPage);

            // Scroll Area Adjustments
            float levelheight = 1.2f / itemsPerPage;
            UIelements.Add(UIScroll(CC_ScrollPage, "0 .1", "1.01 .99", ThemeColor(player, "cui"), itemsPerPage));

            // Loop through levels and add elements
            int num = 0;
            for (level = startIndex; level <= endIndex; level++)
            {
                if (leveldiffculty)
                {
                    requiredlevelxp = (int)Math.Ceiling((levelstart * level) + (level * leveldifficultyamount) * levelstart);
                }
                if (rankdifficulty)
                {
                    requiredlevelxp += levelstart * (rank * rankdifficultyamount);
                }
                if (level == 0)
                {
                    requiredlevelxp = levelstart;
                }

                totalxp += (int)Math.Round(requiredlevelxp);
                
                UIelements.Add(UIInputbackground(num, levelheight, shade, ".01", ".99"), CC_ScrollView);
                UIelements.Add(UILabel($"{level}", num, levelheight, TextAnchor.MiddleLeft, 12, ".01", ".34", "1 1 1 1"), CC_ScrollView);
                UIelements.Add(UILabel($"{(int)Math.Round(requiredlevelxp)}", num, levelheight, TextAnchor.MiddleLeft, 12, ".35", ".68", "1 1 1 1"), CC_ScrollView);
                UIelements.Add(UILabel($"{totalxp}", num, levelheight, TextAnchor.MiddleLeft, 12, ".69", ".99", "1 1 1 1"), CC_ScrollView);
                num++;
            }

            // Pages
            UIelements.Add(UIPanel("0 0", "1 .1", "0 0 0 0"), CC_ScrollPage, "CC_CalCulatorPages");
            int back = page <= 0 ? 0 : page - 1;
            int next = (page + 1) * itemsPerPage < maxlevel ? page + 1 : page;

            // Previous Page Button
            if (page > 0)
            {
                UIelements.Add(UIInputbackground(1, .8f, "0 0 0 1", ".09", ".41", .24), "CC_CalCulatorPages");
                UIelements.Add(UIMenuButton($"CC_CalculatorUI {back}", 1, .75f, 10, ThemeColor(player, "cui"), CCLang("pageprev", player.UserIDString), ".1", ".4", TextAnchor.MiddleCenter, "1 1 1 1", .25), "CC_CalCulatorPages");
            }

            // Next Page Button
            if ((page + 1) * itemsPerPage < maxlevel)
            {
                UIelements.Add(UIInputbackground(1, .8f, "0 0 0 1", ".59", ".91", .24), "CC_CalCulatorPages");
                UIelements.Add(UIMenuButton($"CC_CalculatorUI {next}", 1, .75f, 10, ThemeColor(player, "cui"), CCLang("pagenext", player.UserIDString), ".6", ".9", TextAnchor.MiddleCenter, "1 1 1 1", .25), "CC_CalCulatorPages");
            }
            #endregion

            CuiHelper.AddUi(player, UIelements);
            return;
        }

