        private void CCAdmin_Class(BasePlayer player, string Combatclass = "all")
        {
            if (player == null || !player.userID.Get().IsSteamId() || !player.IsAdmin) return;

            #region Layout
            var UIelements = new CuiElementContainer();
            float height = 0.10f;
            float listheight = 0.075f;
            float classheight = 0.08f;
            int font = 11;
            int row = 1;
            double width = .015;
            double top = .01;
            double bottom = .01;
            #endregion
                    
            UIelements.Add(UIPanel(".20 .01", ".98 .63", "0 0 0 0"), CC_Main, CC_Admin);

            switch (Combatclass)
            {
                case "all":
                    UIelements.Add(UILabel($"{CCLang("CC_admin_003", player.UserIDString)}", row++, listheight, TextAnchor.MiddleCenter, 13, ".02", ".98", "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIMenuButton($"CC_AdminUI class assault", row++, listheight, font, ThemeColor(player, "cui", 0.25), $"{CCLang("assault", player.UserIDString)}", ".3", ".7", TextAnchor.MiddleCenter, "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIMenuButton($"CC_AdminUI class medic", row++, listheight, font, ThemeColor(player, "cui", 0.25), $"{CCLang("medic", player.UserIDString)}", ".3", ".7", TextAnchor.MiddleCenter, "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIMenuButton($"CC_AdminUI class heavy", row++, listheight, font, ThemeColor(player, "cui", 0.25), $"{CCLang("heavy", player.UserIDString)}", ".3", ".7", TextAnchor.MiddleCenter, "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIMenuButton($"CC_AdminUI class demolition", row++, listheight, font, ThemeColor(player, "cui", 0.25), $"{CCLang("demolition", player.UserIDString)}", ".3", ".7", TextAnchor.MiddleCenter, "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIMenuButton($"CC_AdminUI class sniper", row++, listheight, font, ThemeColor(player, "cui", 0.25), $"{CCLang("sniper", player.UserIDString)}", ".3", ".7", TextAnchor.MiddleCenter, "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIMenuButton($"CC_AdminUI class assassin", row++, listheight, font, ThemeColor(player, "cui", 0.25), $"{CCLang("assassin", player.UserIDString)}", ".3", ".7", TextAnchor.MiddleCenter, "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIMenuButton($"CC_AdminUI class scavenger", row++, listheight, font, ThemeColor(player, "cui", 0.25), $"{CCLang("scavenger", player.UserIDString)}", ".3", ".7", TextAnchor.MiddleCenter, "1 1 1 1"), CC_Admin);
                    break;
                case "assault":
                case "medic":
                case "heavy":
                case "demolition":
                case "sniper":
                case "assassin":
                case "scavenger":
                    
                    string mainWeapon = string.Empty;
                    string secondaryWeapon = string.Empty;
                    double mainWeaponDmg = 0;
                    double secondaryWeaponDmg = 0;
                    double maxWeaponDmg = 0;
