        private void CCAdmin_NPC(BasePlayer player, string page = "list", int Id = 0)
        {
            if (player == null || !player.userID.Get().IsSteamId() || !player.IsAdmin) return;

            #region Layout
            var UIelements = new CuiElementContainer();
            float height = 0.10f;
            float listheight = .06f;
            int font = 11;
            int row = 1;
            double top = .01;
            double bottom = .01;
            #endregion

            UIelements.Add(UIPanel(".20 .01", ".98 .63", "0 0 0 0"), CC_Main, CC_Admin);

            switch (page)
            {
                case "list":
                    UIelements.Add(UILabel($"{CCLang("CC_admin_006", player.UserIDString)}", row, height, TextAnchor.MiddleLeft, 13, ".02", ".5", "1 1 1 1"), CC_Admin);
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S038", player.UserIDString)}", row, height, TextAnchor.MiddleLeft, 13, ".5", ".75", "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIMenuButton($"CC_AdminData npc new", row, height, font, ThemeColor(player, "cui", 0.25), $"{CCLang("CC_admin_S040", player.UserIDString)}", ".79", ".99", TextAnchor.MiddleCenter, "1 1 1 1"), CC_Admin);

                    UIelements.Add(UIPanel("0 0", ".98 .9", "0 0 0 0"), CC_Admin, CC_ScrollPage);
                    UIelements.Add(UIScroll(CC_ScrollPage, "0 0", "1.01 .99", ThemeColor(player, "cui"), config.npcList.npcList.Count));

                    row = 1;
                    foreach (var npcs in config.npcList.npcList)
                    {
                        UIelements.Add(UIMenuButton($"CC_AdminData npc delete {npcs.Key}", row, listheight, 13, "0 0 0 0", "⊗", ".02", ".03", TextAnchor.MiddleLeft, "1 0 0 1"), CC_ScrollView);
                        if (npcs.Value.DisplayName == string.Empty)
                        {
                            UIelements.Add(UIMenuButton($"CC_AdminData npc edit {npcs.Key}", row, listheight, font, "0 0 0 0", $"{npcs.Value.DisplayName} ({npcs.Value.ShortPrefabName})", ".05", ".5", TextAnchor.MiddleLeft, "1 1 1 1"), CC_ScrollView);
                        }
                        else
                        {
                            UIelements.Add(UIMenuButton($"CC_AdminData npc edit {npcs.Key}", row, listheight, font, "0 0 0 0", $"{npcs.Value.ShortPrefabName}", ".05", ".5", TextAnchor.MiddleLeft, "1 1 1 1"), CC_ScrollView);
                        }
                        UIelements.Add(UILabel($"{npcs.Value.xp}", row, listheight, TextAnchor.MiddleLeft, 12, ".5", ".99", "1 1 1 1"), CC_ScrollView);
                        row++;
                    }
                    break;
                case "edit":
                    var npc = config.npcList.npcList[Id];
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S039", player.UserIDString, Id)}", row++, height, TextAnchor.MiddleCenter, 13, ".02", ".98", "1 1 1 1"), CC_Admin);
                    row++;
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S036", player.UserIDString)}", row, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIInputbackground(row, height, "0 0 .1 .75", ".5", ".98", top, bottom), CC_Admin);
                    UIelements.Add(UIInput(CC_Admin, $"CC_AdminData npc editnpc ShortPrefabName {Id} {UserInputText}", row, height, 12, $"{npc.ShortPrefabName}", ".5", ".98", TextAnchor.MiddleLeft, "1 1 1 1"));
                    row++;
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S037", player.UserIDString)}", row, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIInputbackground(row, height, "0 0 .1 .75", ".5", ".98", top, bottom), CC_Admin);
                    UIelements.Add(UIInput(CC_Admin, $"CC_AdminData npc editnpc DisplayName {Id} {UserInputText}", row, height, 12, $"{npc.DisplayName}", ".5", ".98", TextAnchor.MiddleLeft, "1 1 1 1"));
                    row++;
                    UIelements.Add(UILabel($"{CCLang("CC_admin_S038", player.UserIDString)}", row, height, TextAnchor.MiddleLeft, 12, ".02", ".5", "1 1 1 1"), CC_Admin);
                    UIelements.Add(UIInputbackground(row, height, "0 0 .1 .75", ".5", ".98", top, bottom), CC_Admin);
                    UIelements.Add(UIInput(CC_Admin, $"CC_AdminData npc editnpc xp {Id} {UserInputText}", row, height, 12, $"{npc.xp}", ".5", ".98", TextAnchor.MiddleLeft, "1 1 1 1"));
                    row++;
                    row++;
                    UIelements.Add(UIMenuButton($"CC_AdminUI npc list", row, height, font, ThemeColor(player, "cui", 0.25), $"{CCLang("CC_admin_S042", player.UserIDString)}", ".02", ".3", TextAnchor.MiddleCenter, "1 1 1 1"), CC_Admin);
                    break;
            }

            CuiHelper.AddUi(player, UIelements);
        }
