        #region API
        public int GetCombatPlayerLevel(ulong player)
        {
            if (!player.IsSteamId()) return 0;
            
            var combatPlayer = GetCombatPlayer(FindPlayer(player));
            if (combatPlayer == null) return 0;

            var combatClass = combatPlayer.combatclass[combatPlayer.currentclass];
            if (combatClass == null) return 0;

            return combatClass.level;
        }

        public Dictionary<string, object> GetCombatClassDisplayInfo(BasePlayer player)
        {
            if (player == null || !player.userID.Get().IsSteamId()) return null;
            var combatPlayer = GetCombatPlayer(player);
            if (combatPlayer == null) return null;
            if (!combatPlayer.combatclass.TryGetValue(combatPlayer.currentclass, out var combatClass) || combatClass == null) return null;
            var className = CCLang(combatPlayer.currentclass, player.UserIDString);
            var xpRequired = GetLevelRequirement(combatPlayer, combatPlayer.currentclass);
            var percent = GetLevelPercent(combatPlayer, combatPlayer.currentclass);
            return new Dictionary<string, object>
            {
                ["ClassName"] = className,
                ["Level"] = combatClass.level,
                ["XP"] = combatClass.xp,
                ["XPRequired"] = xpRequired,
                ["Percent"] = percent
            };
        }
        private void TriggerClassChange(ulong userId, string newClass)
        {
            Interface.CallHook("CombatClassChanged", userId, newClass);
        }
        private void TriggerClassLevelUp(ulong userId, string currentClass, int newLevel)
        {
            Interface.CallHook("CombatClassLevelUp", userId, currentClass, newLevel);
        }
        private void TriggerClassLevelDown(ulong userId, string currentClass, int newLevel)
        {
            Interface.CallHook("CombatClassLevelDown", userId, currentClass, newLevel);
        }
        private void TriggerClassRankUp(ulong userId, string currentClass, int newRank)
        {
            Interface.CallHook("CombatClassRankUp", userId, currentClass, newRank);
        }

