    namespace CombatClassesEx
    {
        public static class CombatPlayerEx
        {
            public static void RunEffect(this BasePlayer player, Vector3 alertLocation, string prefab)
            {
                Effect effect = new Effect();
                effect.Init(Effect.Type.Generic, alertLocation, Vector3.zero);
                effect.pooledString = prefab;
                EffectNetwork.Send(effect, player.Connection);
            }
        }
    }
}
 
